INSERT INTO `creatures` (`id`, `name`, `habitat`, `type`, `story_id`, `place_id`, `name_kanji`, `desc`) VALUES
(1, 'Kuchisake-Onna', 'Тускло освещенные улицы и переулки.', 'Юрей', 'JP001', 'JPK00', '口裂け女', 'Кутисакэ-онна — призрак изуродованной женщины, вернувшейся, чтобы отомстить миру. Её имя происходит от глубокой кровавой раны, пересекающей её лицо, с улыбкой от уха до уха. Она является по ночам одиноким путникам, прикрывая свою суровую пасть тканевой маской, веером или платком.'),
(2, 'Kappa', 'Реки, озёра, пруды. Встречается по всей Японии.', 'Зверь-Ёкай', 'JP002', 'JPK00', '河童', 'Каппы — водные рептильные гуманоиды, обитающие в реках и ручьях, протекающих по Японии. Неуклюжие на суше, они чувствуют себя как дома в воде и процветают в теплые месяцы. Каппы, как правило, размером и формой с человеческого ребенка, но, несмотря на свой небольшой рост, они физически сильнее взрослого мужчины.'),
(3, 'Tanuki', 'Горы и леса. Встречается по всей Японии.', 'Зверь-Ёкай', 'JP003', 'JPK00', '狸', 'Тануки иногда называют енотовидной собакой, но на самом деле это уникальный вид восточноазиатских псовых, напоминающий барсука или енота. Этих застенчивых ночных животных можно встретить на всех японских островах. Статуэтки тануки — популярное украшение домов и магазинов. Их любят не только за их миловидность, но и за связанные с ними истории о проказах и проделках.'),
(4, 'Teke-Teke', 'Городские районы и дороги.', 'Онрё', 'JP004', 'JPK00', 'テケテケ', 'Теке-теке — призрак, появляющийся в ряде городских легенд. Теке-теке почти всегда женщины (хотя в некоторых версиях городской легенды призрак — мужчина). У неё нет нижней части тела; она бегает на руках, издавая характерный звук «теке-теке», от которого и получила своё имя.'),
(5, 'Hanako-san', 'Третья кабинка в женском туалете на третьем этаже.', 'Юрей', 'JP005', 'JPK00', 'トイレの花子さん', 'Ханако-сан — городская легенда о призраке девочки, обитающем в школьных туалетах. Она является героиней школьных легенд по всей Японии, и подробности её истории варьируются от места к месту и от поколения к поколению. Обычно говорят, что она выглядит как школьница с короткой стрижкой, в белой рубашке и красной юбке с подтяжками.'),
(6, 'Sukima-Onna', 'В небольших пространствах или «щелях» внутри и вокруг дома', 'Ёкай', 'JP006', 'JPK00', '隙間女', 'Её внешний вид трудно описать, поскольку она никогда не появляется полностью, обычно Видны лишь её глаза, которые неотрывно следят за человеком из разных щелей.'),
(7, 'Ame-Onna', 'Темные улицы и переулки.', 'Ёкай', 'JP007', 'JPK00', '雨女', 'Амэ-онна — класс ёкаев, появляющихся в дождливые дни и ночи. Они вызывают дождь, куда бы ни пошли, и обвиняются в похищении и увозе детей. Они выглядят как развратные, измождённые женщины, промокшие насквозь дождевой водой. Они слизывают дождь со своих рук, словно дикие звери.'),
(8, 'Kitsune', 'В лесах и диких местах Японии', 'Зверь-Ёкай', 'JP008', 'JPK00', '狐', 'Лисы, или кицунэ, встречаются по всей Японии. Они ничем не отличаются от диких лис, обитающих в других частях света, за исключением своих невероятных магических сил. Милые мордашки и небольшой размер делают их особенно любимыми большинством людей.'),
(9, 'Kyokotsu', 'Колоцы', 'Онрё', 'JP009', 'JPK00', '狂骨', 'Кёкоцу — призрачный скелетообразный дух, выходящий из колодцев и пугающий людей. Он закутан в рваный саван, из которого видны только его выбеленный череп и спутанные волосы.'),
(10, 'Jikininki', 'Старые святилища,храмы и руины.', 'Гуль/Юрей', 'JP010', 'JPK00', '食人鬼', 'Дзикининки — это гули, питающиеся телами умерших. В большинстве случаев они выглядят как обычные люди, но с более чудовищными чертами лица. У них острые, заострённые зубы, которыми они сдирают плоть с недавно умерших.'),
(11, 'Hachishaku-sama', 'Темные и пустынные улицы, часто у подножья горы в Японии', 'Ёкай', 'JP011', 'JPK00', '八尺様', 'Невероятно высокая, около 2,4 метра, Обычно описывается как женщина в белом летнем платье и широкополой шляпе. Также может носить кимоно или туфли на каблуках. У нее длинные черные волосы, которые могут скрывать ее глаза или лицо. Издает повторяющийся звук «по-по-по» как низким, так и высоким голосом, что свидетельствует о ее приближении.'),
(12, 'Jorogumo', 'Cельская местность, леса и пещеры.', 'Ёкай', 'JP012', 'JPK00', '絡新婦', 'Дзёрогумо, известный как золотой ткач кругов. Дзёрогумо — самый известный из паукообразных ёкаев, встречающийся по всему Японскому архипелагу, за исключением северного острова Хоккайдо. Размер их тела в среднем составляет от двух до трёх сантиметров в длину, но они могут вырастать гораздо крупнее; некоторые из них достаточно массивны, чтобы ловить и есть мелких птиц.'),
(13, 'Yuki-onna', 'Горные перевалы; везде, где есть снег.', 'Ёкай', 'JP013', 'JPK07', '雪女', 'Юки-онна охотятся на путников, заблудившихся в снежных бурях, которыми зимой покрываются Японские Альпы. Они обладают неземной красотой: длинными чёрными волосами и тёмными, пронзительными глазами. Их кожа не стареет и бела, как снег, но тела холодны, как лёд. Одного прикосновения достаточно, чтобы человек почувствовал глубокий, несокрушимый холод.'),
(14, 'Nekomata', 'Города, дома.', 'Зверь-Ёкай', 'JP014', 'JPK00', '猫又', 'екоматы встречаются в городах и деревнях и рождаются так же, как и другие бакэнэко. Однако только самые старые и крупные кошки с самыми длинными хвостами, а значит, и самым умным умом, становятся этой могущественной разновидностью. Когда некомата превращается в ёкая, её хвост раздваивается посередине на два одинаковых хвоста.'),
(15, 'Akaname', 'Грязные бани и туалеты.', 'Ёкай', 'JP015', 'JPK00', '垢嘗', 'Аканамэ — маленькие, похожие на гоблинов ёкаи, обитающие только в самых грязных домах и общественных банях. Размером они с ребёнка или невысокого взрослого, хотя обычно кажутся гораздо меньше из-за сгорбленной позы. Их тела голые, а кожа жирная, как и волосы.'),
(16, 'Gashadokuro', 'Обычно встречается вблизи массовых захоронений или полей сражений.', 'Ёкай', 'JP016', 'JPK00', 'がしゃどくろ', 'Гасядокуро — скелетообразные гиганты, бродящие по сельской местности в самые тёмные часы ночи. Их зубы стучат, а кости гремят, издавая звук «гачи-гачи», в честь которого назван этот ёкай. Но они не всегда шумные. Если они наткнутся на человека поздно вечером на дороге, гасядокуро бесшумно подкрадётся и схватит свою жертву, раздавив её руками или откусив голову.'),
(17, 'Rokurokubi', 'Встречается у обычных женщин; также часто встречается в публичных домах.', 'Ёкай', 'JP017', 'JPK00', '轆轤首', 'Днём рокурокуби выглядят как обычные женщины. Ночью же они спят, а их шеи вытягиваются до невероятной длины и свободно бродят. Иногда их головы нападают на мелких животных; иногда они слизывают ламповое масло своими длинными языками; а иногда просто пакостят, пугая окружающих.'),
(18, 'Bakekujira', 'Японское море', 'Ёкай', 'JP018', 'JPK00', '化鯨', 'Бакэкудзира — это ожившие скелеты китов, которые плавают у поверхности моря, поднимаясь на поверхность, как это было при жизни, когда им требовался воздух для дыхания. Их сопровождают множество жутких птиц и странных рыб, а дождливыми ночами они появляются вблизи прибрежных китобойных деревень.'),
(19, 'Ikiryo', 'Густо населённые районы.', 'Юрей', 'JP019', 'JPK00', '生霊', 'Икирё – это души ещё живых людей, временно покинувшие свои тела и передвигающиеся самостоятельно. Они выглядят так же, как и живые существа, из которых они произошли; иногда они принимают призрачный, полупрозрачный облик, а иногда их невозможно отличить от живых.'),
(20, 'Oiwa', 'Неизвестно', 'Онрё', 'JP020', 'JPK00', 'お岩', 'Оива — трагическая и ужасающая онрё из произведения «Ёцуя кайдан», основана на реальных людях, живших в Эдо XVII века,Их история была экранизирована в пьесе кабуки 1825 года «Токайдо Ёцуя кайдан» , которая стала очень популярной и закрепила за Оивой статус самого известного привидения Японии. После этого появилось бесчисленное множество вариаций и адаптаций её истории.'),
(21, 'Hone-onna', 'Тёмные улицы, переулки, кладбища.', 'Юрей', 'JP021', 'JPK00', '骨女', 'Внешне она предстает как красивый скелет или женщина с гниющей плотью, одетая в белый кимоно. Её главная цель — вернуться к любимому, с которым её разлучила смерть.'),
(22, 'Ubume', 'Неизвестно', 'Юрей', 'JP022', '-', '姑獲鳥', 'Убуме может принимать различные обличья: женщина с ребёнком на руках, беременная женщина или окровавленный ходячий труп, несущий недоразвитый плод. В других случаях они просто появляются в виде ужасных, окровавленных беременных женщин, отчаянно кричащих в ночи о помощи.'),
(23, 'Futakuchi-onna', 'Обычно встречается у замужних женщин.', 'Ёкай', 'JP023', 'JPK00', '二口女', 'Футакучи-онна выглядят как обычные женщины, пока не раскрывается их страшная тайна: в задней части черепа, под длинными густыми волосами, находится второй рот, полный зубов и с большими пухлыми губами. Этот второй рот прожорлив и использует длинные пряди своих волосовидных щупалец, чтобы пожирать любую пищу, которую может найти.'),
(24, 'Raiju', 'Молнии', 'Зверь-Ёкай', 'JP024', '-', '雷獣', 'Райдзю – воплощение молнии в животном облике. У них длинные острые когти и свирепые морды. Обычно их считали похожими на волков, собак, тануки, а также на ласок и кошек. Существовали и гораздо более причудливые облики. Иногда говорили, что райдзю похожи на маленьких собак, но с четырьмя задними лапами и двумя хвостами'),
(25, 'Zashiki warashi', 'Гостиная, покрытая татами и другие комнаты', 'Юрей', 'JP025', 'JPK01', '座敷童子', 'Дзасики вараси — это домашние духи. Они любят озорство, их все любят и считают, что они приносят большую удачу и богатство тем, в чьих домах они обитают. Прямые встречи с этими духами редки. Часто трудно разглядеть какие-либо детали, кроме смутной детской формы. Когда их удаётся увидеть, дзасики вараси появляются в виде призрачных детей пяти или шести лет с румяными красными лицами. Мальчики одеты в детские костюмы воинов, а девочки — в узорчатые кимоно и с короткими стрижеными или длинными, завязанными сзади волосами.'),
(26, 'Sugawara no Michizane', 'Неизвестно', 'Онрё', 'JP026', '-', '菅原道真', 'Сугавара-но Митидзанэ был учёным, поэтом и политиком, впавшим в немилость императора и умершим в изгнании. Он жил с 845 по 903 год н. э. и считается одним из величайших учёных и поэтов в истории Японии. После смерти он восстал из могилы в облике гневного онрё, чтобы отомстить тем, кто причинил ему зло при жизни.'),
(27, 'Koma inu', 'Cвятилища, храмы и священные места.', 'Ёкай', 'JP027', 'JPK00', '狛犬', 'Кома-ину — благородные, священные животные, обычно используемые в качестве стражей священных мест. Размеры их могут варьироваться от небольшой собаки до льва, и из-за сходства с обоими животными их часто называют львиными собаками. У них густые, вьющиеся гривы и хвосты, мощное, мускулистое тело, острые зубы и когти. У некоторых кома-ину на голове большие рога, как у единорога. Однако многие безрогие.'),
(28, 'Aka manto', 'Школьные туалеты.', 'Ёкай', 'JP028', 'JPK00', '赤マント', 'Ака-манто — городская легенда, связанная с туалетами, особенно в начальных школах. Этот феномен известен по всей Японии, и существует бесчисленное множество вариаций на одну и ту же тему. Обычно это происходит в определённой кабинке в определённом школьном туалете. Обычно это старый или редко используемый туалет, часто в кабинке со старомодным приземистым унитазом. Часто четвёртая кабинка считается проклятой, поскольку число четыре ассоциируется со смертью.'),
(29, 'Hitotsume kozо', 'Встречается по всей Японии; часто встречается на тёмных улицах.', 'Ёкай', 'JP029', 'JPK00', '一つ目小僧', 'Хитоцумэ-кодзо — маленькие одноглазые гоблины, известные по всей Японии. Они носят бритые головы и одеяния, словно крошечные буддийские монахи. У них длинные красные языки и один огромный глаз.'),
(30, 'Sadako Yamamura', 'Проклятая кассета.', 'Онрё', 'JP030', 'JPK00', '山村貞子', 'Садако появляется в виде молодой женщины с тёмными длинными волосами закрывающие ей лицо и одетой в белое платье.'),
(31, 'Wani', 'Океаны, моря и озера.', 'Зверь-Ёкай', 'JP031', 'JPK00', '和邇', 'Вани — морские чудовища, обитающие в глубоких водоёмах. У них длинные змеевидные тела, плавники, и они могут дышать как воздухом, так и водой. Вани способны принимать человеческий облик, и даже существуют истории о том, как вани и люди влюблялись друг в друга.'),
(32, 'Nure-onna', 'Побережья, реки и другие водоёмы; родом с острова Кюсю.', 'Ёкай', 'JP032', 'JPK00', '濡女', 'Нурэ-онна — вампирические морские змеи, которые бродят по берегам и рекам в поисках людей для еды. Чаще всего они встречаются на берегах острова Кюсю, но есть истории о встречах с нурэ-оннами даже на севере, в префектуре Ниигата, и на востоке, в префектуре Фукусима. Существует две разновидности этого ёкая: одна без рук, которая напоминает огромного морского змея с женской головой, и одна с руками, подобными человеческим.'),
(33, 'Osan gitsune', 'Неизвестно', 'Ёкай', 'JP033', '-', 'おさん狐', 'Осан гицунэ, или просто Осан, — имя ёкай кицунэ (лисы), встречающееся в фольклоре по всей Японии, особенно в Западной. Она хорошо известна тем, что умеет менять облик и подшучивает над людьми. Различные истории о её проступках разбросаны по префектурам Осака, Хиросима и Тоттори, а также по большей части региона Тюгоку. Неясно, относятся ли все они к одному и тому же человеку или к разным кицунэ, которых все зовут Осан. В наши дни женщин, вмешивающихся в чужие отношения, и особенно женщин, замешанных в супружеской неверности, иногда пренебрежительно называют мэгицунэ (женщина-лиса). Говорят, что это слово произошло от Осан гицунэ.'),
(34, 'Taira no Masakado', 'Неизвестно', 'Онрё', 'JP034', '-', '平将門', 'Тайра-но Масакадо был самураем эпохи Хэйан, могущественным воином и великим вождём. Он родился в конце VIII или начале IX века н. э. и был убит в 940 году. Говорят, что после смерти его дух вернулся в виде мстительного призрака и сеял разрушения по всей стране. Наряду с императором Сутоку и Сугаварой-но Митидзанэ он входит в число Нихон Сан Дай Онрё — трёх великих Онрё Японии.'),
(35, 'Onikuma', 'Горные леса.', 'Они', 'JP035', 'JPK00', '鬼熊', 'Медведь, проживший очень долгую жизнь и превратившийся в ёкая, называется оникума, или демонический медведь. Оникума продолжают расти и достигают размеров, значительно превосходящих даже самых крупных медведей. Они ходят на двух ногах и достаточно велики, чтобы утащить коров и лошадей, и легко отодвигают валуны, которые не сдвинут и десять человек.'),
(36, 'Funayurei', 'Моря, океаны, заливы.', 'Юрей', 'JP036', 'JPK00', '船幽霊', 'Это тени утонувших моряков, которые остаются в этом мире, охотясь за своими бывшими друзьями и товарищами, чтобы унести их в море. Как и многие призраки, фунаюрэй появляются в виде мертвых тел, облаченных в белые погребальные одежды. Их можно увидеть ночью, как в новолуние, так и в полнолуние, в особенно штормовые или туманные ночи, а также во время праздника Обон. Фунаюрэй появляются в виде жуткого, светящегося тумана, который становится все ближе и ближе, пока не превратится в корабль с призрачной командой.'),
(37, 'Okuri inu', 'Тёмные горные перевалы, лесные дороги.', 'Зверь-Ёкай', 'JP037', 'JPK00', '送り犬', 'Окури-ину — ночной ёкай, похожий на собаку или волка, обитающий на горных перевалах, лесных дорогах и подобных местах. Они напоминают обычных собак и волков во всём, кроме своей свирепости; они гораздо опаснее своих смертных собратьев.'),
(38, 'Nuppeppо', 'Кладбища, старые храмы.', '??', 'JP038', 'JPK00', 'ぬっぺっぽう', 'Нуппеппо — причудливые и жуткие ёкаи, которых можно встретить в разрушенных храмах, на заросших кладбищах и в других разрушенных местах. Эти существа известны своим отвратительным видом и запахом; от них исходит резкий запах гнилого мяса. Они выглядят как большие, дряблые, почти человекоподобные куски плоти, размером с ребёнка, с бугристыми, недоразвитыми руками и ногами и едва различимыми чертами лица.'),
(39, 'Baku', 'Глубоко в густых лесах.', 'Зверь-Ёкай', 'JP039', 'JPK00', '獏', 'Баку — странное священное существо с телом медведя, головой слона, глазами носорога, хвостом быка и ногами тигра. Несмотря на свой чудовищный вид, баку почитаются как могущественные силы добра и одни из святых защитников человечества.'),
(40, 'Oni', 'Aд. Отдалённые горы, пещеры, острова, заброшенные крепости.', 'Они/Демон', 'JP040', '-', '鬼', 'Они — один из величайших символов японского фольклора. Они крупные и устрашающие, ростом выше самого высокого человека, а иногда и деревьев. Они бывают разных видов, но чаще всего изображаются с красной или синей кожей, растрёпанными волосами, двумя или более рогами и клыкообразными бивнями. Существуют также другие вариации, отличающиеся окраской и количеством рогов, глаз или пальцев рук и ног. Они носят набедренные повязки из шкур огромных зверей. Все они обладают исключительной силой и телосложением, и многие из них — опытные колдуны. Они — свирепые демоны, приносящие бедствия, распространяющие болезни и карающие проклятых в аду.'),
(41, 'Nuribotoke', 'Плохо ухоженные семейные алтари, ветхие дома.', 'Ёкай', 'JP041', 'JPK00', '塗佛', 'Нуриботоке — гротескный зомбиподобный дух, выползающий из буцудана, семейного алтаря, случайно оставленного открытым на ночь. Это мягкий, дряблый, похожий на труп дух с маслянистой чёрной кожей и резким запахом. За ним тянется хвост, похожий на сомика, соединённый с позвоночником. Самая поразительная и пугающая особенность этого духа — его глазные яблоки, дико свисающие из глазниц.'),
(42, 'Chоchin obake', 'Неизвестно', 'Ёкай', 'JP042', '-', '提灯お化け', 'Когда бумажный фонарь, или тётин, достигает преклонного возраста, он может превратиться в тётин-обакэ. Бумага фонаря лопается вдоль одной из деревянных рёбер, образуя разинутый рот с высунутым языком. Из верхней половины фонаря выглядывают один или два глаза. Из тела могут даже вырастать руки или ноги, хотя это случается редко.'),
(43, 'Suppon no yurei', 'Места, где едят мягкотелых черепах.', 'Ёкай', 'JP043', 'JPK00', '鼈の幽霊', 'Суппон — японское название китайской мягкопанцирной черепахи ( Pelodiscus sinensis ). Суппон-но-юрэй — мстительные призраки мягкопанцирных черепах, которые появляются, чтобы отомстить людям, съевшим их. Обычно они выглядят как гигантские призраки с длинными безногими телами и выдающимися заостренными губами, как у мягкопанцирных черепах.'),
(44, 'Taka-onna', 'Кварталы красных фонарей.', 'Ёкай', 'JP044', 'JPK00', '高女', 'Така-онна чаще всего выглядят как обычные, невзрачные женщины. Однако они обладают способностью удлинять своё тело и достигать нескольких метров в высоту. Как и другие ёкаи из борделей, их редко можно увидеть за пределами кварталов красных фонарей, но, тем не менее, они довольно распространённые ёкаи. Пик наблюдений этих ёкаев пришёлся на период Эдо и продолжался вплоть до послевоенного периода — времени расцвета публичных домов и юкаку («районов удовольствий») в Японии.'),
(45, 'Kowai', 'Продуктовые лавки, мусорные свалки', 'Ёкай', 'JP045', 'JPK01', '狐者異', 'Коваи - призрак обжоры, перенёсшего свою одержимость едой в следующую жизнь, превратившись после смерти в этого ёкая. Он принимает облик гротескного человека с лисьими чертами лица, налитыми кровью глазами, острыми зубами и длинным, пускающим слюни языком.'),
(46, 'Kama itachi', 'В основном Японские Альпы, но потенциально везде, где водятся ласки.', 'Зверь-Ёкай', 'JP046', 'JPK00', '鎌鼬', 'Кама-итати три ласки с острыми как бритва когтями, кружащихся в яростном вихре и обрезающих у встреченных на пути людей кожу на ногах.'),
(47, 'Onryо', 'Встречается по всей Японии.', 'Онрё', 'JP047', 'JPK00', '怨霊', 'Онрё - то призраки людей, умерших с такой сильной страстью — ревностью, яростью или ненавистью, — что их души не могут переселиться. Вместо этого они превращаются в могущественных, гневных духов, жаждущих мести всему, с чем сталкиваются.'),
(48, 'Jinja hime', 'Глубокие озера и океаны', 'Ёкай', 'JP048', 'JPK00', '神社姫', 'Дзиндзя-химэ — змееподобное существо длиной около шести метров. У него два рога на голове, длинный хвост, спинной плавник и ласты. Лицо у него как у женщины. Он напоминает нингё, японскую русалку.'),
(49, 'Furi', 'Горы и скалы.', 'Зверь-Ёкай', 'JP049', 'JPK00', '風狸', 'Фури — дикие звери из гор Китая. Размером они примерно с тануки или речную выдру, а формой напоминают обезьяну. У них красные глаза, короткие хвосты, чёрная шерсть с леопардовым узором и сине-зелёные гривы, тянущиеся от носа до хвоста.'),
(50, 'Kasane', 'Неизвестно', 'Онрё', 'JP050', '-', '累', 'Касанэ - Призрак одетая в белое кимоно, с изуродованным лицом покрытым синяками и ссадинами. Образ был взят из довольно старого фильма «Касанэ га фути» («Озеро Касанэ»), 1957 года выпуска, основанного на реалььных событиях XVII века.');
INSERT INTO `deity` (`id`, `kami`, `name_kanji`, `story_id`, `domain`, `desc`) VALUES
(1, 'Amaterasu-Omikami', '天照大御神', 'kami_S001', 'Солнце, свет, жизнь.', 'Аматэрасу Омиками — это Японская богиня Солнца, главный ками (божество) в синтоизме и почитаемый предок императорской семьи'),
(2, 'Tsukuyomi-no-Mikoto', '月読命', 'kami_S002', 'Луна, ночь, время.', 'Цукуёми-но-Микото — это Синтоистский бог луны и ночи в японской мифологии., один из трёх главных божеств, рождённых богом-творцом Идзанаги после его путешествия в царство мёртвых.'),
(3, 'Susanoo-no-Mikoto', '素戔嗚尊', 'kami_S003', 'Море, бури, разрушение.', 'Сусаноо-но-Микото - это главный синтоистский ками (божество) бурь и моря, младший брат богини солнца Аматэрасу и центральная фигура японской мифологииИзвестный своим хаотичным и буйным нравом'),
(4, 'Inari Okami', '稲荷大神', 'kami_S004', 'Рис, урожай, плодородие, лисы.', 'Ина́ри - один из самых почитаемых ками в Японии. Его (или её) почитают как покровителя урожая и изобилия, торговли и ремёсел. Чаще всего Ина́ри изображают в мужском или женском облике, иногда даже в андрогинном — образ меняется в зависимости от региона и верований.'),
(5, 'Izanagi-no-Mikoto', '伊邪那岐命', 'kami_S005', 'Творение мира, жизнь, очищение.', 'Бог-созидатель, вместе с Изанами создавший японские острова и многих ками. После смерти супруги спустился в Ёми (подземный мир), но, ужаснувшись увиденному, бежал. Совершив очищение от скверны, породил трёх великих богов: Аматэрасу (солнце), Цукуёми (луна) и Сусаноо (бури). Символизирует творение и ритуальную чистоту.'),
(6, 'Izanami-no-Mikoto', '伊邪那美命', 'kami_S006', 'Смерть, загробный мир, тьма.', 'Супруга Изанаги, богиня-созидательница и мать многих ками. Умерла при рождении огненного божества Кагуцучи и отправилась в Ёми, став владычицей мира мёртвых. Символизирует плодородие и смерть, хранит грань между жизнью и загробным царством.'),
(7, 'Hachiman', '八幡神', 'kami_S007', 'Война, защита, самураи.', 'Бог войны и покровитель Японии. Почитается как защитник воинов и страны. Часто изображается в воинских доспехах. Символ военной доблести и справедливой защиты.'),
(8, 'Fujin', '風神', 'kami_S008', 'Ветер, бури.', 'Бог ветра, один из старейших синтоистских ками. Изображается с большим мешком, из которого выпускает ветра. Символизирует стихию и перемены.'),
(9, 'Raijin', '雷神', 'kami_S009', 'Гром, молнии, штормы.', 'Бог грома и молний, часто сопровождает Фудзина. Изображается с барабанами, которыми вызывает гром. Символизирует силу природы и устрашение.'),
(10, 'Omoikane', '思兼神', 'kami_S010', 'Мудрость, интеллект, решения.', 'Бог мудрости и размышлений. Призывается для принятия решений и советов другим ками. Связан с мифом о возвращении Аматэрасу из пещеры.'),
(11, 'Ebisu', '恵比寿', 'kami_S011', 'Рыболовство, удача, богатство.', 'Один из семи богов удачи. Покровитель рыбаков, торговцев и богатства. Изображается с удочкой и морским уловом.'),
(12, 'Okuninushi', '大国主', 'kami_S012', 'Медицина, любовь, магия, нация.', 'Бог лечения, брака и страны. Известен мифом о спасении зайца Инаба. Символизирует заботу, доброту и удачу в отношениях.'),
(13, 'Kagutsuchi', 'カグツチ', 'kami_S013', 'Огонь, разрушение.', 'Бог огня, сын Изанаги и Изанами. Его рождение привело к смерти матери. Связан как с разрушительной силой пламени, так и с очищением.'),
(14, 'Konohanasakuya-hime', '木花開耶姫', 'kami_S014', 'Цветы, вишня, вулканы.', 'Богиня весны, цветущей сакуры и вулканов. Супруга бога Ниниги. Символизирует красоту, жизнь и быстротечность существования.'),
(15, 'Ame-no-Uzume-no-Mikoto', '天宇受売命', 'kami_S015', 'Радость, смех, искусство.', 'Богиня веселья и танцев. Именно она с танцем вывела Аматэрасу из пещеры. Символизирует смех, праздник и обрядовые танцы кагура.'),
(16, 'Sarutahiko Okami', '猿田彦大神', 'kami_S016', 'Дороги, путешествия, проводник.', 'Бог-проводник, ведущий ками и людей. Символизирует пересечение дорог и направление в жизни.'),
(17, 'Ukemochi no Kami', '保食神', 'kami_S017', 'Еда, пища, изобилие.', 'Богиня пищи. Убита Цукуёми за «осквернённое угощение», из её тела возникли новые продукты. Символизирует бесконечный источник пищи.'),
(18, 'Watatsumi no Kami', '綿津見神', 'kami_S018', 'Море, океан, драконы.', 'Морской бог, владыка подводного царства. Часто связан с драконами и подводными дворцами. Символизирует глубину и мощь океана.'),
(19, 'Oyamatsumi', '大山祇神', 'kami_S019', 'Горы, охота, природа.', 'Бог гор и охоты. Считается покровителем лесов, горных земель и воинов. Символизирует силу природы и защиту земли.'),
(20, 'Tenjin', '天神', 'kami_S020', 'Обучение, мудрость, поэзия.', 'Обожествлённый учёный Сугавара-но Митидзанэ. Бог учёбы, экзаменов и науки. Его почитают студенты и ученики.');
INSERT INTO `object` (`id`, `object_name`, `desc`, `story_id_o`) VALUES
(1, 'Кукла Окику', 'Кукла, связанная с храмом Манне́ндзи в Хоккайдо. Считается вместилищем духа умершего ребёнка, о чём свидетельствует аномальный рост её волос. Объект используется как пример предмета, ставшего носителем сверхъестественного.', 1),
(2, 'Колодец Окику', 'Колодец, связанный с легендой о девушке Окику и её гибели. Считается источником повторяющегося счёта и проявления призрачных звуков. Выступает пространственным объектом, закреплённым за конкретной трагической историей.', 2),
(3, 'Телефон Мэри', 'Мистический телефонный объект, связанный с серией звонков от сущности по имени Мэри. Устройство выступает каналом связи, по которому передаётся информация о приближении угрозы. Чем дольше разговор, тем ближе источник опасности.', 3),
(4, 'Бакэ-Дзори', 'Ожившие соломенные сандалии, относящиеся к цукумогами — предметам, получившим дух после длительного использования. Проявляют активность ночью, издавая звуки и пугая людей. Символизируют одушевление бытовых вещей.', 4),
(5, 'Лес Аокигахара', 'Лес у подножия горы Фудзи, известный как место с искажённой ориентацией и подавляющей атмосферой. В мифологическом и современном контексте рассматривается как пространство, притягивающее заблудших и беспокойные духи.', 5),
(6, 'Тоннель/Деревня Инунаки', 'Легендарная заброшенная деревня в Японии, официально исключённая из правового поля. Считается местом, где не действуют законы, а нарушившие запреты подвергаются преследованию. Объект современной городской мифологии.', 6),
(7, 'Станция Кисараги', 'Несуществующая железнодорожная станция, появляющаяся вне официальных маршрутов. Попавшие на неё люди не могут вернуться обычным способом и сталкиваются с искажением времени и пространства. Известна как интернет-легенда.', 7),
(8, 'Сироунэри', 'Бытовой дух, связанный с предметами из ткани и сетчатыми материалами. Проявляется в ночное время, создавая ощущение удушья и вторжения в личное пространство. Относится к малозаметным, но опасным ёкаям.', 8),
(9, 'Поврежденная статуя Дзидзо', 'Каменная статуя бодхисаттвы Дзидзо, установленная для защиты детей и путников. Повреждённые или заброшенные статуи считаются предвестниками несчастий. Объект религиозного и мифологического значения.', 9),
(10, 'Тоннель Киётаки', 'Горный тоннель в Японии, известный изменением восприятия длины и пространства. Считается местом скопления духов погибших рабочих. Внутри тоннеля зафиксированы зеркальные и зрительные аномалии.', 10);
INSERT INTO `object_story` (`id`, `o_story_name`, `story`) VALUES
(1, 'Кукла Окику', 'Согласно одной из самых известных японских легенд, кукла Окику принадлежала маленькой девочке по имени Окику, жившей в начале XX века на острове Хоккайдо. Кукла была приобретена старшим братом девочки во время поездки в город Саппоро и подарена ей в качестве игрушки. Окику быстро привязалась к кукле и практически не расставалась с ней, считая её своим личным сокровищем.\r\nСпустя некоторое время девочка тяжело заболела и умерла. После её смерти семья, находясь в трауре, поместила куклу на домашний алтарь в память о ребёнке. Со временем родственники заметили странное явление: волосы куклы, которые изначально были короткими, начали отрастать. Попытки подстричь их не дали результата — спустя время волосы вновь становились длиннее.\r\nСчиталось, что в куклу вселился дух умершей Окику, не желающий покидать мир живых. Семья восприняла происходящее как знак и передала куклу в буддийский храм Манне́ндзи, где монахи согласились хранить её и проводить регулярные ритуалы очищения. По сей день кукла находится в храме, а её волосы продолжают расти, что периодически подтверждается служителями.\r\nВ японской мифологии кукла Окику стала одним из самых известных примеров цукимоно — объектов, в которых закрепляется дух человека. Легенда подчёркивает представление о том, что сильная эмоциональная привязанность может связать душу с физическим предметом, превратив его в носитель сверхъестественного.'),
(2, 'Колодец Окику', 'Легенда о колодце Окику уходит корнями в более ранний период японской истории и связана с трагической судьбой служанки по имени Окику. Согласно преданию, она служила в доме самурая и отвечала за сохранность десяти драгоценных тарелок, являвшихся ценным имуществом её господина.\r\nОднажды одна из тарелок пропала. В зависимости от версии легенды, тарелка была либо украдена, либо уничтожена самим хозяином дома, желавшим обвинить Окику. Несмотря на её мольбы и уверения в невиновности, девушка подвергалась жестоким допросам и наказаниям. В конечном итоге Окику была убита и сброшена в колодец, находившийся во дворе усадьбы.\r\nПосле её смерти жители начали слышать по ночам странные звуки, доносившиеся из колодца. Призрак Окику якобы поднимался из глубины и начинал считать тарелки вслух: «одна… две… три…» — доходя до девяти и затем издавая пронзительный крик, осознавая отсутствие десятой. Этот счёт повторялся снова и снова, не находя завершения.\r\nКолодец стал восприниматься как место, в котором застряла душа, не способная обрести покой. В японской культуре эта история стала одним из классических примеров онрё — мстительного духа, возникшего из-за несправедливости и насильственной смерти. Колодец Окику превратился в символ цикличного страдания и невозможности завершения трагической истории.'),
(3, 'Телефон Мэри', 'Легенда о телефоне Мэри относится к современной японской городской мифологии и получила широкое распространение в конце XX — начале XXI века. В центре истории находится сущность по имени Мэри, которая связывается с человеком посредством телефонных звонков, постепенно приближаясь к нему.\r\nСогласно распространённой версии, человек получает первый звонок от Мэри с сообщением о том, что она находится в определённом месте, например у входа в дом или на улице. Каждый последующий звонок сообщает о новом, более близком местоположении: «Я уже на лестнице», «Я у двери», «Я за твоей спиной». Интервалы между звонками сокращаются, создавая нарастающее напряжение.\r\nТелефон в данной легенде выступает не просто средством связи, а каналом, через который сверхъестественная сущность отслеживает жертву. Попытки выключить устройство, выбросить его или сменить номер, как правило, не приводят к спасению — звонки продолжаются, либо источник угрозы проявляется напрямую.\r\nПроисхождение Мэри в разных версиях различается: она может быть духом погибшей девушки, проклятым голосом или абстрактной сущностью, существующей только в момент контакта. Общим элементом остаётся неизбежность её приближения и невозможность избежать финального столкновения.\r\nЛегенда о телефоне Мэри отражает страх перед технологиями и потерей контроля над личным пространством. Она демонстрирует, как привычный предмет повседневного использования превращается в источник угрозы, стирая границу между безопасной средой и вторжением извне.'),
(4, 'Бакэ-Дзори', 'Бакэ-дзори — один из представителей цукумогами, одушевлённых предметов, которые, согласно японским верованиям, обретают дух после долгих лет использования. В данном случае объектом становится пара соломенных сандалий дзори, которые были брошены, забыты или больше не использовались хозяином.\r\nСчитается, что по прошествии ста лет предмет может пробудиться и получить собственное сознание. Бакэ-дзори появляются преимущественно ночью, когда люди спят, и передвигаются самостоятельно, подпрыгивая или скользя по земле. Их присутствие сопровождается характерными звуками шагов и тихим бормотанием, призванным напугать человека.\r\nВ отличие от более агрессивных ёкаев, бакэ-дзори редко наносят физический вред. Их основная цель — напугать, вызвать беспокойство или напомнить человеку о неуважительном отношении к вещам. В традиционной интерпретации бакэ-дзори являются своеобразным наказанием за пренебрежение предметами повседневного быта.\r\nЛегенда о бакэ-дзори отражает японское представление о том, что даже неодушевлённые вещи обладают скрытой сущностью и заслуживают бережного отношения. В мифологическом контексте этот объект служит примером перехода обыденного предмета в сферу сверхъестественного без трагического события или насильственной смерти.'),
(5, 'Лес Аокигахара', 'Аокигахара — лес, расположенный у подножия горы Фудзи, который издавна воспринимается как особое и тревожное место. В традиционных представлениях он считался пространством, где легко заблудиться, так как густая растительность и неровный рельеф искажают восприятие направления и расстояния.\r\nВ японском фольклоре Аокигахара связывается с духами юрэй и онрё — душами людей, не сумевших покинуть мир живых. Считалось, что в лесу обитают сущности, способные сбивать путников с пути, заставляя их уходить всё глубже и терять связь с внешним миром. Эти представления существовали задолго до появления современных интерпретаций.\r\nВ более поздний период Аокигахара получил репутацию места, связанного с человеческим отчаянием и внутренней изоляцией. Однако в мифологическом смысле лес рассматривается не как источник зла, а как пространство отражения человеческого состояния. Он не преследует и не нападает, но усиливает одиночество и внутренние переживания тех, кто в него входит.\r\nАокигахара выступает как лиминальное пространство — граница между присутствием и исчезновением, между движением вперёд и остановкой. В отличие от проклятых мест, связанных с насилием, этот лес воспринимается как молчаливый наблюдатель, существующий вне человеческой морали и оценки.'),
(6, 'Тоннель/Деревня Инунаки', 'Деревня Инунаки считается одним из самых известных проклятых мест современной японской мифологии. Согласно легенде, она расположена в труднодоступной горной местности и официально исключена из правового поля государства. На подступах к деревне якобы установлена табличка с предупреждением о том, что после пересечения границы «законы Японии более не действуют».\r\nПроисхождение проклятия деревни в разных версиях легенды отличается. В одних источниках Инунаки описывается как место жестоких преступлений и насилия, в других — как сообщество, сознательно изолировавшееся от внешнего мира и отвергшее современные нормы. Независимо от версии, деревня воспринимается как пространство, где привычный социальный порядок был полностью утрачен.\r\nЛюди, попадавшие в Инунаки, по преданиям, сталкивались с враждебным отношением местных жителей, исчезновениями и невозможностью покинуть территорию тем же путём, которым они пришли. Средства связи либо перестают работать, либо становятся бесполезными. Само пространство деревни описывается как замкнутое и подавляющее.\r\nВ мифологическом контексте Инунаки представляет собой пример «отверженного места» — пространства, сознательно выведенного за пределы общества. Легенда отражает страх перед полной утратой законов, морали и защиты, которые обычно гарантирует государство, и показывает, что происходит, когда человек остаётся один на один с территорией, не признающей внешнего мира.'),
(7, 'Станция Кисараги', 'Станция Кисараги является одной из наиболее известных японских интернет-легенд, впервые появившейся на анонимных форумах в начале XXI века. Согласно рассказу, человек, находясь в обычном поезде, внезапно замечает, что поезд не останавливается на привычных станциях и продолжает движение за пределами известного маршрута.\r\nВскоре поезд прибывает на станцию под названием «Кисараги», которая отсутствует на официальных картах и расписаниях. Сама станция выглядит пустынной и заброшенной, а окружающая местность лишена признаков современной инфраструктуры. Попытки покинуть станцию или найти обратный путь оказываются безуспешными.\r\nЛюди, оказавшиеся на станции Кисараги, сталкиваются с искажением времени и пространства. Средства связи либо перестают работать, либо передают фрагментарную информацию. В некоторых версиях легенды упоминаются странные звуки, отдалённые шаги и появление неясных фигур в темноте.\r\nСчитается, что Кисараги представляет собой пограничное пространство, существующее вне привычной реальности. Те, кому удаётся вернуться, по преданиям, возвращаются изменёнными — утратившими часть воспоминаний или ощущение связи с прежней жизнью. В мифологическом контексте станция Кисараги символизирует страх утраты контроля над направлением собственного пути.'),
(8, 'Сироунэри', 'Сироунэри — один из малозаметных ёкаев, относящихся к категории духов, связанных с предметами быта и тканями. В традиционных представлениях он возникает из старых, долго не использовавшихся тканевых изделий, таких как сетки, полотна или элементы одежды, оставленные без внимания.\r\nСчитается, что сироунэри проявляется преимущественно ночью, когда человек находится в состоянии сна или полудрёмы. Его присутствие сопровождается ощущением давления на тело, удушья или ограничения движений. В некоторых версиях легенды говорится, что сироунэри обвивает жертву, подобно ткани или сети, лишая возможности сопротивляться.\r\nОпасность сироунэри заключается не в прямом нападении, а в его незаметности. Он не издаёт громких звуков и не имеет ярко выраженного облика, из-за чего его воздействие часто воспринимается как кошмар или естественное физиологическое состояние. Это делает его особенно коварным, так как жертва не осознаёт источник угрозы.\r\nВ мифологическом контексте сироунэри символизирует страх вторжения в личное пространство и уязвимость человека во сне. Легенда отражает представление о том, что даже самые обычные предметы могут стать источником опасности при утрате контроля и внимания.'),
(9, 'Поврежденная статуя Дзидзо', 'Статуи Дзидзо представляют собой каменные изображения бодхисаттвы Дзидзо, широко распространённые в Японии. Они устанавливаются у дорог, на перекрёстках, возле кладбищ и храмов и считаются защитниками детей, путников и душ умерших.\r\nСогласно народным верованиям, Дзидзо помогает душам умерших детей преодолевать загробный путь, защищая их от страданий. В связи с этим статуи часто украшаются красными шапочками, шарфами и игрушками, оставляемыми в качестве подношений. Эти предметы служат символами заботы и просьбы о защите.\r\nСуществует поверье, что повреждённые, заброшенные или осквернённые статуи Дзидзо могут стать источником несчастий. Считается, что нарушение покоя или уважения к статуе приводит к утрате её защитной функции, а иногда — к появлению тревожных знаков и странных явлений вблизи места установки.\r\nВ мифологическом и культурном контексте статуя Дзидзо выступает не как источник зла, а как объект баланса между защитой и наказанием. Легенды, связанные с Дзидзо, подчёркивают важность почтительного отношения к сакральным объектам и ответственности человека перед духовным миром.'),
(10, 'Тоннель Киётаки', 'Тоннель Киётаки расположен в горной местности Японии и известен как одно из наиболее тревожных проклятых мест. Он был построен в начале XX века в тяжёлых условиях, при использовании принудительного труда. Считается, что многие рабочие погибли во время строительства из-за обвалов, истощения и отсутствия должной безопасности.\r\nСогласно легендам, души погибших не покинули это место и остались связаны с тоннелем. Посетители утверждают, что при прохождении через него возникает ощущение искажения пространства: длина тоннеля кажется меняющейся, а выход может казаться значительно дальше, чем должен быть на самом деле. Некоторые свидетели сообщают о появлении человеческих силуэтов на стенах или в глубине прохода.\r\nОдним из наиболее известных элементов легенды является зеркало, якобы установленное внутри тоннеля. Считается, что если посмотреть в него, можно увидеть не своё отражение, а призрачный образ или искажённую фигуру. В ряде версий говорится, что зеркало способно «забирать» человека, оставляя его сознание внутри тоннеля.Тоннель Киётаки рассматривается как пример места, где трагическое прошлое повлияло на восприятие реальности. \r\nВ мифологическом контексте он выступает пространственным объектом, в котором границы между физическим миром и миром духов становятся нестабильными.');
INSERT INTO `place` (`id`, `place_name`, `desc`, `geo`, `climate`) VALUES
('JPK001', 'Рисирифудзи', 'Рисирифудзи - священная гора острова Рисири, субпрефектура Соя.\nЭта гора, одиноко поднимающаяся над холодным морем Японского моря, с древности считалась местом, где граница между миром живых и духами становится тоньше. Её вершина почти всегда скрыта облаками, будто сама гора прячет свой лик от любопытных глаз.\n\nМестные рыбаки и старейшины острова верили, что внутри горы спит бог ветра, чьё дыхание вызывает туманы и штормы. Считалось, что если туман с Рисири накроет берег — это значит, что дух проснулся и охраняет свои владения.\nВ некоторых устных легендах Рисирифудзи называют «Горой-стражем Севера», ведь именно она стоит последним барьером между людьми и бурей, приходящей с северных морей.', 'Он расположен в восточной части острова Рисири в Японском море , в западной части региона Соя . Рельеф острова пересеченный, а поселения разбросаны вдоль побережья, зажатого между горами и морем. Главные поселения — Осидомари на севере и Ониваки на юге.', 'Благодаря близости к морю разница температур между летом и зимой невелика. Летом температура редко достигает 30 градусов, а зимой опускается до -10 градусов. Ветер сильный, среднегодовая скорость ветра превышает 5 метров.'),
('JPK002', 'Асахикава', 'Асахикава - город среди ветров и теней Хоккайдо.\nРасположенный у подножия горы Дайсэцу, Асахикава с давних времён считался местом пробуждения духов зимы. Легенды айнов и японских переселенцев здесь смешались, создавая особую атмосферу: будто воздух хранит отголоски обоих миров.\n\nВ старых рассказах упоминается, что в окрестных лесах обитает “Хираму” - дух инея, что замораживает дыхание тех, кто слишком громко говорит ночью. Считалось, что если человек шёл через заснеженный перевал и начинал шептать молитву, то ветер вокруг становился мягче - знак того, что дух услышал и позволил пройти.\n\nГород также известен как место, где вода и снег «разговаривают». По преданиям, под толщей льда течёт скрытая река, ведущая к «зеркалу духов» - озеру, которое показывается лишь избранным в сне или в минуты отчаяния.', 'Город Асахикава расположен в котловине Камикава , крупнейшей котловине на Хоккайдо, в месте слияния рек Исикари , Ушишубэ , Чубэ и Биэй. Горы Хоронаи, горы Тэсио и холмы Арасияма расположены в западной части города, простираясь с севера на юг. Река Исикари размыла горы Хоронаи, образовав долину Камуикотан. В горах Дайсэцу обитают такие животные, как пищухи , рыжие лисицы и белки Хоккайдо.', 'Асахикава известна как одно из самых холодных мест Японии — зимой температура нередко опускается ниже −25°C. Снег ложится уже в ноябре и держится до конца марта.\nИз-за того что город расположен в котловине, ветра здесь почти нет, но именно это создаёт ощущение плотного, стоячего холода, который проникает под кожу. Лето короткое, но яркое: зелень появляется мгновенно, как будто земля спешит прожить всю жизнь за несколько недель тепла.'),
('JPK003', 'Саппоро', 'Саппоро - город, выросший на снегу. Его прямые улицы и одинаковые кварталы будто нарочно выстроены так, чтобы запутать память: всё кажется знакомым, но каждый поворот уводит в другое место. Среди жителей ходит поверье, что под городом, в старых тоннелях времён освоения Хоккайдо, спят духи первопоселенцев, не выдержавших зим и одиночества.\nИногда, во время снежных бурь, можно услышать, как что-то шепчет под ногами — говорят, это те, кто остались там, внизу, зовут вернуться домой.\n\nНа окраинах Саппоро, ближе к холмам Маруяма и Мойва, часто видят бледные фигуры в традиционных одеждах, которые исчезают при приближении. Считается, что они охраняют древние айновские святилища камуи, затерянные между дорогами и новыми домами.', 'Расположенный в юго-западной части равнины Исикари , город имеет площадь 1121,26 км² , что примерно равно площади Гонкона. Город протянулся на 42,30 км с востока на запад и на 45,40 км с севера на юг. Равнинная центральная часть представляет собой аллювиальный конус выноса, образованный рекой Тоёхира .', 'Зимы здесь длинные и снежные — город погружается в белую тишину на полгода. Снег не тает неделями, превращая улицы в бескрайние зеркала.\nТемпература колеблется от −10°C до −20°C, а в сильные метели Саппоро будто исчезает во времени — здания и дороги сливаются в одну сплошную пелену.\nЛето мягкое, но мимолётное: тепло приходит лишь на пару месяцев, словно сам город не верит, что может быть по-другому.'),
('JPK004', 'Фукуока', 'Фукуока - древний прибрежный край, где море дышит памятью. В старину здесь сходились торговцы, монахи и странники, привозя с собой не только товары, но и истории, проклятия и духи других земель. Говорят, что под вечер, когда солнце садится за горизонт Генкайского моря, вода становится зеркалом — в нём можно увидеть лица тех, кто не успел вернуться домой.\n\nСтарые рыбаки из прибрежных деревень рассказывают, что во время туманов слышны голоса, зовущие по имени. Те, кто откликаются, исчезают бесследно — будто море возвращает себе долг.\nНа окраинах города сохранились старые синтоистские святилища, где вместо обычных каменных кицунэ стоят фигуры без лиц, истёртые ветром. Считается, что это стражи рубежей — хранители границы между живыми и ушедшими.', 'Фукуока расположена на северном краю острова Кюсю, обращённом к Корейскому проливу. Благодаря этому она стала первым местом соприкосновения Японии и материка, своеобразным мостом между культурами и верованиями.\nЕё земли простираются от морских берегов до холмов, поросших вечнозелёными деревьями, где туман держится даже в полдень.', 'Фукуока - город влажного дыхания моря. Здесь редко бывает снег, но зимой туманы густые, как дым, а летом — тяжёлые дожди, смывающие очертания улиц.\nТемпература мягкая — от +5°C зимой до +33°C летом.\nКогда жара накрывает побережье, ночами от воды поднимается пар, и по нему будто идут тени. Говорят, в такие ночи можно услышать шёпот из дальних портов и плеск тех, кто возвращается с другого берега.'),
('JPK005', 'Йокогама', 'Йокогама — город контрастов. В её сердце бьётся Мина́то Мираи 21, район будущего, где небоскрёбы, морской бриз и огни ночных улиц создают картину живого мегаполиса. Но стоит свернуть в старые кварталы — и время будто замедляется: узкие улочки, чайные лавки, старинные храмы и уютные парки напоминают о прошлом.\nЙокогама — символ открытости: именно здесь в XIX веке Япония впервые начала принимать иностранные корабли после веков изоляции. Поэтому город хранит в себе дух смешения культур — китайские кварталы, западные особняки, старые верфи и японские храмы сосуществуют в гармонии.\nВечерами, когда над бухтой сгущается туман, Йокогама превращается в место с особой атмосферой — словно на границе мира людей и моря духов.', 'Йокогама находится в префектуре Канагава, всего в тридцати километрах к югу от Токио. Это второй по численности населения город Японии, раскинувшийся вдоль побережья Токийского залива.\nЙокогама — крупнейший порт страны и одна из ключевых точек для международной торговли, культурных обменов и морских маршрутов. Её гавань словно ворота между Японией и остальным миром.', 'Йокогама имеет умеренно влажный субтропический климат.\nЗимой — мягко и спокойно, снег редкость, а воздух пахнет солью и железом от порта.\nВесной цветут парки, летом жара смягчается морским ветром, а осенью город утопает в янтарных тонах.\nДожди часты, особенно в июне и сентябре, когда над бухтой часто висят туманы, создавая иллюзию, будто город плавно растворяется в море.'),
('JPK006', 'Нагано', 'Нагано — это сочетание древней тишины и вечных гор. Здесь расположены старинные дзэн-храмы, деревни, затерянные в туманных долинах, и бескрайние поля яблонь. Столицей префектуры является город Нагано, известный своим храмом Дзэнко-дзи — одним из старейших и наиболее почитаемых буддийских храмов Японии.\nГоры префектуры стали домом для многих легенд — от духов рек и горных богинь до снежных демонов и призраков заблудших путешественников.\nБлагодаря своему рельефу, Нагано стала центром зимнего спорта: здесь проходили Зимние Олимпийские игры 1998 года. Но за спортивной стороной прячется более мистическая аура: густые леса, старые дороги к святилищам и уединённые деревни, где до сих пор сохраняются древние обряды и поверья.', 'Префектура Нагано расположена в самом центре острова Хонсю, и не имеет выхода к морю. Она окружена горами с трёх сторон, что делает её естественной крепостью Японии. Через Нагано проходят две цепи японских Альп — Кисо и Хида, и именно благодаря этому рельефу регион стал символом японской горной культуры.', 'Климат в Нагано континентальный. Зимы здесь холодные и снежные, особенно в горах, где температура часто опускается ниже −10 °C, создавая идеальные условия для зимних курортов, таких как Хакуба. Лето же мягкое, без удушающей влажности, типичной для приморских регионов. Весной здесь особенно красиво — цветущие деревья на фоне снежных вершин создают один из самых поэтичных пейзажей в стране.'),
('JPK007', 'Тоттори', 'Тоттори — одна из самых «тихих» и уединённых префектур Японии. Её визитная карточка — песчаные дюны Тоттори, крупнейшие в стране. Они тянутся вдоль побережья на несколько километров, создавая ощущение, будто ты стоишь не в Японии, а на границе пустыни и моря.\nНо за пределами дюн пейзаж резко меняется: горы, леса и рисовые поля соседствуют с уютными прибрежными посёлками, где рыбаки всё ещё выходят в море на маленьких деревянных лодках.\nГлавный город — Тоттори — небольшой, но очень колоритный: здесь смешаны традиции и элементы ретро-Японии 1970-х, словно время идёт чуть медленнее.\nНа юге префектуры возвышается гора Дайсэн, священная вершина, часто сравниваемая с Фудзи по красоте и форме. Считается, что в древности она была одним из центров синтоистских и буддийских обрядов, связанных с поклонением горам.', 'Префектура Тоттори расположена на западном побережье острова Хонсю, обращённая к Японскому морю. На юге простираются горы Тюгоку, а на севере — широкие пляжи и дюны. Такое сочетание гор и моря делает Тоттори удивительно разнообразным по ландшафту — от прибрежных равнин до скалистых перевалов.', 'Климат Тоттори умеренный, с заметным морским влиянием. Зимой часты снегопады, особенно в горах, но температуры редко бывают экстремальными. Лето влажное и тёплое, с лёгкими морскими бризами. Осень в Тоттори считается одним из самых красивых сезонов — когда горы окрашиваются в красно-золотые тона, а воздух становится прозрачным и свежим.'),
('JPK008', 'Такэда', 'Такэда — одно из тех мест, где время будто остановилось.Он известен руинами замка Такэда, который стоит на горе Кōдзёсан и часто окутан облаками, из-за чего его называют «Небесным замком». Когда туман ложится в долину, крепость словно парит над облаками — это зрелище не зря сравнивают с замком из сна. Город сам по себе небольшой, но имеет глубокие корни: здесь чувствуется дух эпохи самураев, следы старинных дорог и забытых храмов. Рядом шумят водопады Хару́дзо, где, по местным легендам, живут духи воды, а в ночи можно услышать эхо барабанов, доносящихся со склонов — будто отголоски старых ритуалов. Такэда хранит ауру заброшенного величия: место, где величие прошлого сливается с покоем настоящего.', 'Город Такэда расположен в префектуре Оита на острове Кюсю, в глубине горного региона, окружённого густыми лесами и речными долинами. Это уединённое место, скрытое среди холмов, где туман опускается на рассвете, а горы словно охраняют город от внешнего мира.', 'Климат в Такэде — влажный и умеренный, с выраженной сезонностью.\nЗимой здесь прохладно, возможен лёгкий снег на вершинах,\nа летом — густые туманы и влажный воздух, наполненный ароматом земли и хвои.\nВесна и осень — время особого очарования: цветущие сакуры и красные клёны отражаются в реках, а утренние облака делают пейзажи похожими на старинные японские гравюры.\nИз-за окружающих гор воздух здесь кажется плотным и глубоким — как дыхание древнего леса.'),
('JPK009', 'Коя', 'Коя — духовное сердце секты Сингон и одно из самых мистических мест Японии.\nЗдесь, более тысячи лет назад, святой Кукай (Кобо Дайси) основал монашеский комплекс, который со временем вырос в настоящий \"город храмов\".\nВ Кое более сто двадцать монастырей, каждый из которых хранит собственную легенду, а над всем этим витает запах ладана и холодный шёпот ветра.\nОсобое место занимает Оку-но-ин — древнее кладбище, где среди тысяч каменных статуй и мшистых ступ находятся гробницы самураев, монахов и простых людей, и где, по преданию, сам Кукай пребывает в вечной медитации, ожидая пробуждения Будды Майтрейи.\nГоворят, ночью там можно услышать, как сквозь ветви деревьев проходят души странников, а свет фонарей — это не свет, а дыхание ушедших.', 'Гора Коя расположена в префектуре Вакаяма, в сердце горного массива Кйи.Это священное место скрыто среди густых кедровых лесов, и дорога туда идёт по узким серпантинам, словно сама природа оберегает его тайну.Высота горы и отдалённость делают Кою отдельным миром — словно городом монахов над облаками.', 'Климат в районе Кои — влажный и прохладный из-за высоты.\nЗимой тут лежит снег, весной туманы опускаются на храмы, летом прохладный ветер доносит аромат хвои,\nа осенью багряные клены делают весь горный склон похожим на пламя.\nДни здесь коротки, а ночи тихие — будто сам воздух зовёт к молчанию и размышлению.'),
('JPK010', 'Йосино', 'Йосино издавна считался священной землёй и одним из центров синкретизма синто и буддизма.\nГора Йосинояма была местом поклонения ещё до буддистских времён — здесь отшельники и монахи практиковали аскезу, а духи горы, как считалось, защищали странников.\nПозже Йосино стал символом весеннего пробуждения и вдохновения: поэты, художники и странники приходили сюда, чтобы увидеть сакуру и ощутить, как коротка и прекрасна жизнь.\nВ древности это было место, куда уходили те, кто хотел исчезнуть из мира — в буквальном и духовном смысле.\nДаже сейчас здесь можно почувствовать тишину, которая давит и чарует одновременно.\nЙосино — как сон, в котором не знаешь, проснулся ли ты, или всё ещё смотришь на танец лепестков в тумане.', 'Город Йосино находится в преfектуре Нара, у подножья горы Йосинояма.\nЭто место окружено мягкими холмами и густыми лесами, а весной горы покрываются тысячами цветущих сакур, превращая весь пейзаж в живую акварель.\nЙосино — словно врата между древней Японией и её поэзией.', 'Климат умеренно-влажный, с мягкой зимой и насыщенным летом.\nВесной воздух наполняется ароматом цветов, летом в горах прохладно и свежо,\nа осенью Йосино окрашивается в золото и алый.\nЗимой тишина становится почти полной — всё покрывает иней, а треск ветвей под снегом звучит как дыхание горного духа.\nТуманы здесь — почти живые, будто старые хранители спускаются с вершин, чтобы напомнить, что ты гость в их мире.');
INSERT INTO `story` (`id`, `name`, `story`, `source`) VALUES
('JP001', 'Kuchisake-Onna', 'Говорят, что когда-то она была невероятно красивой женой молодого самурая или, может, врача. Она была тщеславна и гордилась своей красотой больше всего на свете. Муж её был человеком ревнивым и жестоким. Однажды, вернувшись домой, он застал её с любовником. Или, может, ему просто почудилось, что она ему изменяет — ведь она так прекрасна, что не может принадлежать только ему. Бешенство ослепило его. Он схватил свой боевой нож или, может, скальпель, если он был врачом, и, привязав её, с криком: «Кто теперь назовёт тебя красивой?!» — провёл лезвием от одного уха до другого, разрезав ей щёки и создав ту самую, жуткую, неестественную улыбку.\r\n\r\nОна умерла в муках, и её дух, отягощённый обидой, тщеславием и жаждой мести, не ушёл в мир иной. Он остался бродить в нашем мире, являясь тем, кто осмелится говорить о красоте.\r\n\r\nЕё образ отпечатался в сознании целого поколения. Ты идешь домой из школы один, солнце клонится к закату, тени становятся длинными и зловещими. На пустынной улице, у старой стены, за спиной слышится лёгкий шелест — шаги, слишком тихие, чтобы быть человеческими. Ты оборачиваешься, и вот она стоит.\r\n\r\nВысокая женщина в длинном пальто, с шарфом, закрывающим нижнюю часть лица, и в хирургической маске — странная деталь для тех лет. Но самая жуткая — это её глаза. Глубокие, тёмные, полные нечеловеческой печали и злобы.\r\n\r\nОна подходит к тебе ближе, и её голос звучит глухо, словно из-под земли: «Я красивая?» (Watashi, kirei?)\r\n\r\nСердце у тебя замирает. Ты киваешь, не в силах вымолвить слово, потому что от неё веет леденящим холодом. Тогда она медленно, очень медленно, снимает маску или шарф. И ты видишь это: её лицо искажено чудовищным шрамом, рот растянут от уха до уха в вечной, оскаленной улыбке-ране. Зубы обнажены, как у горгульи.\r\n\r\nИ она задаёт свой главный, ужасный вопрос, вторично: «А ТЕПЕРЬ я красивая?» (Kore demo, kirei?)\r\n\r\nВ этот момент решается твоя судьба. Это ловушка, магический договор, из которого нет лёгкого выхода.\r\n\r\nЕсли ты скажешь «нет», рассердив её, она мгновенно достанет откуда-то ножницы, большой окровавленный нож или тот самый скальпель, и разрежет твой рот точно так же, как её собственный. Ты станешь таким же, как она.\r\n\r\nНо если ты, дрожа, скажешь «да», согласившись с её уродством, она уйдёт. Но ненадолго. Она будет следовать за тобой. Ты будешь слышать её шаги за дверью своей комнаты, видеть её тень в окне. И когда ты, в конце концов, уснёшь, она войдет и... «сделает тебя красивым», то есть разрежет тебе рот, чтобы ты стал её вечным спутником.', 'Школьный слух'),
('JP002', 'Kappa', 'в старые времена, когда боги ещё ходили по земле, а императоры слушали шёпот драконов, в провинции Этиго жил-был старый рыбак. Звали его Ёсиро. Не был он ни богат, ни знатен, но сердце у него было доброе, а руки трудолюбивые. Каждое утро, пока солнце ещё только цеплялось за вершины гор, он выходил в море на своей утлой лодчонке.\r\n\r\nОднажды на море опустился такой густой туман, что не видно было ни берега, ни неба. Ёсиро греб наугад, и вдруг его лодка мягко ткнулась носом во что-то. Он думал, к скале пристал, но, присмотревшись, увидел, что это не скала, а маленький необитаемый островок, которого он раньше никогда не видел. Сошёл он на берег и услышал странный звук — будто кто-то плачет. Шёл он на этот звук и в глубине небольшой пещеры нашёл он её.\r\n\r\nОна сидела на камне, завернувшись в плащ из перьев, и слёзы её были крупнее жемчужин. Но это была не женщина. Из-под плаща виднелся клюв, а перепончатые лапы виднелись подолом кимоно. Это была каппа — речное дитя.\r\n\r\n«Что случилось, дитя вод?» — спросил старик, не испугавшись её вида.\r\n\r\nКаппа подняла на него глаза, полные слёз. «Я заблудилась. Шла по подводному туннелю и вышла здесь, а обратный путь отлив завалил камнями. Я не могу вернуться домой, в свою реку. Без воды из моей родной реки я слабею. Солёный воздух моря иссушает меня».\r\n\r\nИ тут старик Ёсиро, недолго думая, сказал: «Садись в мою лодку. Я отвезу тебя к устью твоей реки».\r\n\r\nДорогой каппа, которую звали Кавако, рассказывала ему о подводном мире. О городах из речного жемчуга, о танцах карпов кои при лунном свете, о том, как водяные духи помогают дождям наполнять рисовые поля. А Ёсиро рассказывал ей о людях, о своих внуках, о праздниках, где едят лепёшки моти.\r\n\r\nОн довёз её до реки, и Кавако, коснувшись родной воды, сразу воспряла духом. Её кожа засияла, а в глазах заиграли весёлые блики. «Ты спас мне жизнь, старик, — сказала она. — А у нас, капп, есть правило: за добро платить добром. Возьми это».\r\n\r\nОна протянула ему странный шар, похожий на слиток, но мягкий и излучающий лёгкое свечение. «Это лекарство от всех болезней. Маленький кусочек, растворённый в воде, исцелит любую хворь. Но храни его в тайне, ибо алчность людей не знает границ».\r\n\r\nЁсиро вернулся в свою деревню. Вскоре его сосед, маленький мальчик Таро, тяжело заболел. Лекари лишь разводили руками. И тогда Ёсиро вспомнил о даре Кавако. Он отломил крошечный кусочек от того шара, растворил в воде и дал выпить мальчику. Наутро Таро был здоров и играл, как ни в чём не бывало.\r\n\r\nВесть о чудесном исцелении разнеслась по всей деревне. К Ёсиро потянулись больные со всей округи. Он никому не отказывал, брал лишь ту плату, что люди могли ему предложить — горсть риса, связку редиса, сушёную рыбу. И всех он исцелял. Его стали почитать как святого.\r\n\r\nНо слух о волшебном лекарстве дошёл до жадного старосты деревни, человека жестокого и властного. Он явился к Ёсиро и потребовал: «Отдай мне сокровище, старик! Оно должно принадлежать тому, кто управляет этой землёй!»\r\n\r\nЁсиро отказался. Тогда староста со своими слугами ворвался ночью в его дом, связал старика и отнял волшебный шар.\r\n\r\nОбрадованный староста решил испытать силу дара на себе. Он был здоров как бык, но отломил большой кусок и проглотил его, мечтая обрести бессмертие. Но не тут-то было. Лекарство, данное в благодарность чистому сердцу, в руках алчного человека обратилось в яд. Живот старосты распух, по телу пошли чёрные пятна, и к утру его нашли мёртвым. А волшебный шар исчез — говорят, он растаял, как лёд на весеннем солнце.\r\n\r\nВ ту же ночь к опечаленному Ёсиро, который сидел на берегу и горевал о том, что его доверчивость привела к беде, из воды вышла Кавако.\r\n\r\n«Не печалься, старик, — сказала она. — Дар был дан тебе, и только твоя добрая воля могла им распоряжаться. Я пришла не с пустыми руками. Я научу тебя тайным знаниям — каким травам с горных склонов, омываемых водопадами, под силу лечить людей. Это знание никто не сможет у тебя отнять».\r\n\r\nС тех пор Ёсиро стал великим травником. Он прожил долгую жизнь, исцеляя людей, а когда его время пришло, говорят, он не умер, а просто ушёл однажды вечером к реке и не вернулся. А на том месте, где его видели в последний раз, теперь бьёт чистый родник, вода из которого будто бы до сих пор обладает целебной силой.\r\n\r\nИ с тех пор в тех краях верят, что если ты добр и честен, каппа может стать тебе другом. А если жадничаешь и лжёшь — берегись, ведь тогда она может и за щиколотку утащить, и насмехаться над тобой, выливая воду из ложбинки на своей голове — источника её силы.', 'Фольклорный сборник'),
('JP003', 'Tanuki', 'В стародавние времена, в одной глухой деревушке у подножия горы, жил-был старый монах. Жил он в маленьком храмике и вёл жизнь праведную, но уж очень тоскливую. И был у него один-единственный друг — старый, мудрый (как тогда казалось) Тануки, который частенько приходил к нему погреться у огня и послушать чтение сутр.\r\n\r\nНо однажды монах нашёл в лесу осиротевшего ежёнка. Пожалел он зверька, принёс в храм и стал ухаживать за ним. И вот беда — Тануки взревновал! Видит он, что монах теперь всё своё внимание и лучшие кусочки еды отдаёт колючему найденышу, а его, старого друга, забыл.\r\n\r\nЗакипела в Тануки обида. \"Ладно, — думает он, — я тебе покажу! Я не какой-то там еж, я могу стать кем угодно!\"\r\n\r\nРешил он проучить монаха. Выждал, когда тот ушёл в деревню за подаянием, подкараулил ежа в саду и... проглотил его! Не со зла, нет — Тануки по натуре не убийца. Просто чтобы убрать конкурента.\r\n\r\nВернулся монах, а ежа нет. Искал-искал, звал-звал — тщетно. Заподозрил он Тануки, но тот лишь невинно хлопал своими круглыми глазками и почёсывал свой большой, пушистый живот.\r\n\r\nТут у монаха кончилось терпение. Схватил он посох и как крикнет: \"Ах ты, неблагодарный тварь! Я тебя приютил, а ты моего приёмного сына сожрал! Ступай вон из моего храма и чтоб духу твоего тут не было!\"\r\n\r\nИспугался Тануки, пустился наутёк. Но обида в его сердце никуда не делась. \"Прогоняешь меня? Ну и ладно! Я теперь сам себе хозяин! Буду веселиться!\"\r\n\r\nИ началось...\r\n\r\nВ первую же ночь он вспомнил, что монах учил его, как силой мысли и дыхания менять форму. Сел Тануки на опушке, надул свою мохнатую грудь, сконцентрировался... и превратился в самого монаха! Идёт он обратно к храму, стучит в дверь. Настоящий монах открывает — а на пороге стоит его точная копия!\r\n\r\n\"Кто ты?!\" — вскричал монах.\r\n\"Я — это ты!\" — отвечает Тануки его же голосом.\r\n\"Не может быть! Я — это я!\"\r\n\"А я — это ты!\"\r\n\r\nНачался у них такой спор, что на шум сбежалась вся деревня. Никто не мог понять, кто из них настоящий. В конце концов, деревенский староста, человек хитрый, предложил: \"Кто из вас пройдёт по тонкому мосту над горной речкой, тот и настоящий! Фальшивый оробеет и упадёт!\"\r\n\r\nНастоящий монах, уверенный в своей правоте, смело ступил на мост и перешёл на другую сторону. Тануки, недолго думая, последовал за ним. Но он-то знал, что он ненастоящий! И как только он дошёл до середины, его сердце ёкнуло от страха. Концентрация ослабла, иллюзия дрогнула... и все увидели, как из-под рясы \"монаха\" вдруг показался пушистый хвост, затем лапы... и на мосту уже сидел сам Тануки, смущённо почёсывающий за ухом.\r\n\r\nДеревня покатилась со смеху! Монах, конечно, был в ярости, но поделать ничего не мог. Тануки, довольный произведённым эффектом, смылся в лес.\r\n\r\nС тех пор он и пошёл по свету с одной лишь целью — устраивать самый безобидный, но самый дурацкий переполох.\r\n\r\nОн может превратиться в гигантского, горустопного монстра и ночью наступать на твой дом, заставляя его трястись, будто от землетрясения. А наутро ты увидишь лишь один-единственный след — огромный, как таз, и пахнущий сакэ.\r\n\r\nОн может прикинуться поющим котлом-тягамой и устроить целое шествие из домашней утвари по деревне, пока вся посуда в доме не оживёт и не пустится в пляс.\r\n\r\nА его знаменитые... э-э-э... достоинства? Да, он может превратить свою мошонку во что угодно! В огромный плащ, чтобы укрыть целую процессию от дождя, в парадные ворота для храма, или даже в целый корабль, на котором он плавает по морю, распевая похабные песенки. Это не похабщина, нет! Это символ его безграничного изобилия и щедрости!\r\n\r\nИ если ты встретишь в горах одинокого путника, который предложит тебе выпить, а потом его лицо начнёт расплываться, превращаясь в усатую морду с добрыми глазами — не бойся. Это он, Тануки. Он может стащить у тебя кошелёк, но он же оставит тебе вместо него сухой лист, который наутро превратится в монету. Он — дух веселья, глупости и непредсказуемой магии, который напоминает нам: не стоит относиться к жизни слишком серьёзно. А то как бы он не превратил твою новую соломенную шляпу в тарелку с лапшой, пока ты спишь!', 'Фольклорный сборник'),
('JP004', 'Teke-Teke', 'Всё началось с одной молодой девушки. Говорят, звали её О-Цуки, или может быть Каёко. Имя стёрлось, остался только ужас. Она была прекрасна, как ночь с полной луной, и так же безрассудно влюблена. Как это часто бывает, её возлюбленный был не того круга, и их связь была тайной. Однажды ночью, опаздывая на свидание к нему, она в спешке перебегала железнодорожные пути.\r\n\r\nОна не услышала грохот приближающегося скорого поезда. Или, может, её толкнули. Говорят даже, что это был её ревнивый возлюбленный, который сам и назначил ей встречу в этом гиблом месте, чтобы разом покончить с неудобной связью.\r\n\r\nПоезд не успел затормозить.\r\n\r\nУдар был страшным. Девушку перерезало пополам колесами поезда. Её нижняя часть тела осталась на одной стороне путей, а верхняя — на другой. Она умерла не сразу. В последние секунды жизни она с нечеловеческой ясностью осознала две вещи: свою ужасную боль и страшное предательство.\r\n\r\nИ эта смесь агонии, обиды и ярости не позволила её духу уйти.\r\n\r\nТеперь она бродит по ночам вблизи железнодорожных станций, пустырей и длинных тёмных аллей. Но бродит она не так, как все. У неё нет ног. Она передвигается на локтях, волоча за собой окровавленный торс, и её изуродованные руки цокают по асфальту, издавая тот самый звук, от которого леденеет кровь: «Тэкэ-тэкэ-тэкэ…» — звук, похожий на стук костяных пальцев по бетону.\r\n\r\nОна не просто бродит. Она ищет. Ищет свои ноги. Ищет того, кто виноват в её смерти. Но больше всего она ищет замену.\r\n\r\nЕсли ты, идя ночью, услышишь этот леденящий душу стук «тэкэ-тэкэ-тэкэ», — не оборачивайся. Беги. Но самое страшное — это её голос. Он доносится будто из-под земли, хриплый, полный нечеловеческой тоски.\r\n\r\n«Где мои ноги?» (Ashi wa doko?)\r\n\r\nЕсли ты по глупости или из любопытства обернёшься, ты увидишь её. Существо с длинными растрёпанными чёрными волосами, скрывающими лицо, которое стремительно, с помощью рук, ползёт в твою сторону, издавая этот ужасный цокающий звук.\r\n\r\nИ тогда у тебя будет лишь один вопрос, от которого зависит твоя жизнь.\r\n\r\nОна спросит тебя тем самым хриплым шёпотом: «Ты не видел мои ноги?» (Watashi no ashi, shiranai?)\r\n\r\nЭто ловушка. Неважно, что ты ответишь. Если ты скажешь «нет», она в ярости набросится на тебя и своим телом, словно гигантской гусеницей, обовьёт тебя, а её острые, как бритва, кости разрежут тебя пополам. Она заберёт твои ноги, чтобы наконец-то стать целой, а твою безжизненную верхнюю часть тела бросит на рельсы.\r\n\r\nНо есть, говорят, один шанс спастись. Очень хитрый и очень рискованный. Нужно ответить ей не «да» или «нет», а крикнуть: «Здесь! Они здесь!» — и указать в сторону, противоположную от пути твоего бегства. Например, бросить в сторону свою куртку или сумку и крикнуть: «Твои ноги тут!»\r\n\r\nЖажда найти свои ноги настолько сильна, что её дух на секунду отвлечётся. Она поползёт к указанному месту, и в этот миг у тебя будет несколько драгоценных секунд, чтобы бежать без оглядки. Бежать до самого дома, не останавливаясь и не оборачиваясь, пока не захлопнешь дверь за собой.\r\n\r\nГоворят, что если тебе удалось обмануть её таким образом, ты будешь в безопасности. Но следующей ночью на том же месте она будет ждать уже кого-то другого. Её тоска и ярость вечны.', 'Школьный слух'),
('JP005', 'Hanako-san', 'Говорят, что в третьей кабинке туалета на третьем этаже старой школьной постройки живёт призрак маленькой девочки. Её зовут Ханако-сан.\r\n\r\nКогда-то, давным-давно, во время войны или Может быть в послевоенные годы, она была обычной ученикой младших классов. История её смерти теряется во мгле и имеет много версий. Самая распространенная гласит, что она пряталась в школьном туалете во время воздушного налёта. Бомба попала прямо в школу, и та часть здания, где были туалеты, обрушилась, похоронив её под завалами.\r\n\r\nДругая, ещё более жестокая версия, говорит, что её преследовал и напал на неё в туалете маньяк, может быть даже незнакомец, который пробрался в школу, или, может быть, свой же учитель. Она пыталась спрятаться в кабинке, но он настиг её там.\r\n\r\nТретьи шепчут, что над ней жестоко издевались одноклассники, и в один ужасный день, не выдержав насмешек, она пришла в школьный туалет и покончила с собой.\r\n\r\nТак или иначе, её душа не нашла покоя. Она осталась в том самом месте, где её жизнь так трагически оборвалась, — в школьном туалете.\r\n\r\nИ вот как её можно встретить.\r\n\r\nПодойди к третьей кабинке на третьем этаже. Обычно эта кабинка либо всегда закрыта, либо из неё веет странным холодом. Ты должен три раза постучать в дверь и спросить: «Ханако-сан, ты здесь?» (Hanako-san, iru no?)\r\n\r\nСначала будет тишина. А потом… из-за двери послышится тихий, детский, но до жути безэмоциональный голос. Он ответит: «Да-а-а… я здесь» (Hai… iru yo.)\r\n\r\nЕсли ты откроешь дверь — ты увидишь её. Маленькую девочку в старомодной, немного выцветшей школьной форме и с короткой стрижкой. Иногда говорят, что у неё красная юбка. А иногда — что всё её лицо бледное, как мел, и на нём нет ни капли выражения.\r\n\r\nИ тогда с тобой случится одна из трёх вечей, в зависимости от версии легенды:\r\n\r\nСамая популярная версия: Она спросит тебя: «Сыграешь со мной в джянкэн?» (в «камень-ножницы-бумагу»). Если ты согласишься и выиграешь, она исполнит твоё желание или может быть просто исчезнет, позволив тебе уйти. Но если ты проиграешь… она заберёт тебя с собой. В свой мир, за зеркало, в канализацию под туалетом — никто не знает, куда именно. Ты исчезнешь навсегда.\r\n\r\nБолее жуткая версия: Она не станет играть. Она просто появится перед тобой, и ты увидишь её настоящую форму. Говорят, что снизу, под её красной юбкой, не ноги, а тело дракона или что-то чешуйчатое и чудовищное. Увидев это, можно умереть от страха на месте.\r\n\r\nСамый страшной исход: Она не просто заберёт тебя. Она утащит тебя в унитаз. Да-да, именно так. Её рука, холодная и мокрая, схватит тебя, и она, несмотря на свои маленькие размеры, с нечеловеческой силой втянет тебя в канализационный сток, в тёмную, зловонную бездну, откуда никто и никогда не возвращался.\r\n\r\nНо иногда, говорят, с ней можно договориться. Можно принести ей подношение — коробочку с соком или леденец, и тогда она будет к тебе благосклонна и может быть даже защитит тебя от школьных хулиганов.', 'Школьный слух'),
('JP006', 'Sukima-Onna', 'Ты переезжаешь в новую, но довольно старую квартиру. В Токио или Осаке, где дома стоят вплотную друг к другу, а стены иногда тоньше рисовой бумаги. После тяжёлого дня ты ложишься спать. Комната погружается в тишину, нарушаемую лишь редкими звуками проезжающих машин.\r\n\r\nИ вот, в этой тишине, ты замечаешь её.\r\n\r\nВ углу комнаты, в месте, где плохо состыковались обои, или где от времени треснула штукатурка, образуется узкая, тёмная щель. Сукима. Ты не придаёшь этому значения. Все дома стареют.\r\n\r\nНо на следующую ночь тебе кажется, что в этой щели что-то есть. Что-то тёмное. Ты ворочаешься, пытаешься уснуть, и твой взгляд снова и снова возвращается к тому углу. И тогда ты понимаешь, что это тёмное — не просто тень. Это — глаз.\r\n\r\nОдин огромный, блестящий, неестественно вытянутый по вертикали человеческий глаз, который пристально смотрит на тебя из щели. Она не моргает. Она просто наблюдает\r\n\r\nОна — дух, существо, которое может сжаться до толщины листа бумаги и проникнуть в любое, даже самое микроскопическое пространство между стенами, дверью и косяком, шкафом и стеной. Её тело гибкое, как у угря, а кожа бледная, почти прозрачная. Но самое жуткое — это её лицо, утыкающееся в щель, и тот самый огромный глаз, который видит всё, что ты делаешь в своей комнате.\r\n\r\nОткуда она взялась? Никто не знает наверняка. Говорят, что она могла быть женщиной, замурованной заживо в стене в наказание за измену или по воле ревнивого мужа. Или может быть она умерла от одиночества в своей тесной квартирке, и её дух слился с самим домом. Её душа, сплющенная давлением городской жизни, теперь ищет утешения в том, чтобы наблюдать за жизнью других.\r\n\r\nНо её наблюдение — не безобидно.\r\n\r\nСначала это просто чувство дискомфорта. Ты заклеиваешь щель скотчем. Наутро скотч аккуратно содран. Ты затыкаешь дырку тряпкой. Ночью ты просыпаешься от тихого шороха — и видишь, как тряпка медленно вываливается из щели, будто кто-то вытолкнул её изнутри. А тот глаз всё так же смотрит на тебя.\r\n\r\nОна не делает ничего. Не нападает. Не говорит. Она просто наблюдает. Но её присутствие источает леденящий холод и парализующий ужас. Ты перестаёшь спать. Ты боишься переодеваться в комнате. Ты не можешь расслабиться. Ты чувствуешь себя животным в клетке, за которым непрерывно следят.\r\n\r\nИ вот приходит ночь, когда ты не выдерживаешь. Ты вскакиваешь с кровати, хватаешь рулон скотча, чтобы наконец заклеить эту проклятую щель намертво. Ты подходишь к стене, и твои пальцы касаются шероховатой поверхности.\r\n\r\nИ тут щель… шевельнулась.\r\n\r\nОна не просто трещина. Это — её рот. Два вертикальных разреза по бокам щели приоткрываются, обнажая ряд острых, как иглы, зубов. И из щели доносится тихий, шипящий, полный неземной тоски шёпот, который, кажется, исходит из самой стены:\r\n\r\n«Тетсукете… Не закрывай меня…» (閉けないで… «Shimenaide…»)\r\n\r\nИли, может быть, она скажет: «Смотри… Смотри на меня…»\r\n\r\nВ этот момент становится ясно, что она не просто призрак за стеной. Она в стене. Она и есть сама щель. И если ты попытаешься её закрыть, она может решить, что наблюдения ей уже недостаточно. Что ей нужно стать ближе.\r\n\r\nГоворят, что если ты проявишь к ней сострадание, оставишь её в покое и может быть даже будешь иногда с ней разговаривать, она может стать твоим безмолвным «соседом» и даже защитит тебя от других духов. Но если ты попытаешься от неё избавиться, запирая её… она найдёт новую щель. Прямо над твоей кроватью. И в одну из ночей ты проснёшься от того, что из этой щели на тебя будет капать тёплая вода… или свисать длинные, чёрные, как смоль, волосы.\r\n\r\nОна — олицетворение страха перед тотальным отсутствием приватности, перед ощущением, что даже в четырёх стенах своего дома ты никогда не бываешь по-настоящему один. И самое страшное в ней — это не клыки и не проклятия, а этот одинокий, немигающий глаз в щели, который напоминает тебе: ты всегда на виду. Всегда.', 'Фольклорный сборник'),
('JP007', 'Ame-Onna', 'Бывают такие дни, когда дождь идёт не переставая, словно само небо оплакивает что-то. И в такие дни, если ты одинок и подавлен, ты можешь встретить её.\r\n\r\nОбычно это происходит на пустынной улице, в парке, на окраине города, когда дождь уже льёт несколько суток подряд. Она стоит под одним деревом или просто идет под зонтом, но странность в том, что её зонт… старомодный, бумажный, а может быть и вовсе порванный. Или его у неё нет вовсе, но её платье и волосы почему-то лишь слегка влажные, будто капли дождя боятся её намочить.\r\n\r\nОна невероятно красива. Бледная, почти прозрачная кожа, длинные чёрные волосы, мокрые от дождя, и огромные, полные неизбывной печали глаза. Она выглядит потерянной и одинокой.\r\n\r\nОна может обратиться к тебе, одинокому путнику. Её голос тихий, едва слышный сквозь шум дождя.\r\n\r\n«Ты не проводишь меня до дома? Мне страшно одной».\r\n\r\nИли она просто будет молча идти рядом, бросая на тебя грустные взгляды. Сердце любого мужчины дрогнет. Её хочется защитить, утешить, пригласить в тёплое, сухое место.\r\n\r\nИ вот тут таится ловушка. Если ты проявишь к ней доброту — предложишь свой зонт, плащ, проводишь её — она последует за тобой. Не только в тот день. Она привяжется к тебе.\r\n\r\nС этого момента дождь пойдет везде, где появляешься ты. Солнечные дни для тебя закончатся. Ты будешь выходить из дома — и с ясного неба начнут накрапывать капли. Ты поедешь в командировку в другой город — и там встретишь ливень. Дождь станет твоим вечным спутником, фоном твоей жизни. Влажность будет пропитывать всё твоё существо, вещи в твоём доме покроются плесенью, а в твоей душе поселится та же тоска, что и в её глазах.\r\n\r\nПочему? Потому что Амэ-онна — это дух женщины, умершей от горя. Самая распространенная версия гласит, что она ждала своего возлюбленного — может быть рыбака, может быть солдата — который ушёл и не вернулся. Она ждала его каждый день на берегу или у дороги, под дождём и ветром, пока её сердце не разорвалось от печали. Её душа стала одним целым с дождём, её тоска — тем, что она приносит с собой.\r\n\r\nДругая версия: она умерла, утонув или замёрзнув под холодным осенним ливнем. Её дух ищет тепла, которое она потеряла, и тянется к живым, чтобы хоть ненадолго согреться.\r\n\r\nОна не злая. Она несчастная. Она не хочет тебя убить, как Кутисакэ-онна. Она хочет быть с тобой. Но её любовь — это любовь-проклятие. Она приносит с собой вечную сырость, депрессию и меланхолию. Жизнь с ней — это жизнь в перманентных сумерках, под нескончаемый стук капель по крыше.\r\n\r\nИзбавиться от неё почти невозможно. Она стала частью твоей жизни, как стал частью её дождь. Говорят, если ты сумеешь наступить на её тень в солнечный день (но когда же ты его увидишь?), она может исчезнуть. Или если ты предложишь ей высушить её мокрое кимоно у огня, а сам уйдёшь и не вернёшься, она maybe отпустит тебя.\r\n\r\nНо чаще всего мужчины, к которым привязалась Амэ-онна, постепенно угасают. Они либо смиряются со своей участью, живя в вечной сырости и тоске, либо, обезумев от отсутствия солнца, кончают с собой, пополняя собой легион таких же печальных духов.', 'Фольклорный сборник'),
('JP008', 'Kitsune', 'В эпоху Хэйан, когда императорский двор утопал в роскоши и интригах, жил-был молодой, но небогатый аристократ. Назовём его Киёмару. Он был учтив, хорошо сложен, но состояние его рода таяло на глазах. Однажды ночью, возвращаясь из столицы по тёмной дороге, он увидел в свете луны прекраснейшую женщину, какую только можно представить. Её звали Юки. Черты её лица были безупречны, кожа — бела как фарфор, а в глазах светилась загадочная мудрость. Она была одета в кимоно невероятной красоты, но странного, не совсем человеческого покроя.\r\n\r\nОни полюбили друг друга с первого взгляда. Юки была умна, остроумна, и, что удивительно, все дела Киёмару после свадьбы пошли в гору. Его урожаи становились богаче, его лошади — сильнее, а на политическом небосклоне ему неизменно сопутствовала удача. Казалось, сама фортуна была влюблена в него. Юки родила ему нескольких прекрасных детей, которые были не по годам смышлёны.\r\n\r\nНо была в ней одна странность. Она терпеть не могла собак. Лай пса заставлял её бледнеть и уходить в дальние покои. А ещё иногда, в сумерках, Киёмару мог заметить, как отбрасываемая ею тень была не совсем человеческой — у неё был длинный, пушистый хвост.\r\n\r\nШли годы. Однажды их старший сын, резвясь в саду, упал и сильно рассек руку. Не думая ни о чём, кроме страха за ребёнка, Юки бросилась к нему. И в этот момент из-за кустов выскочил старый пёс сторожа, который обычно был на привязи. Увидев его, Юки вскрикнула от ужаса, и прежде чем она смогла совладать с собой, из-под её роскошного кимоно выскользнул огненно-рыжий хвост. Один, два... целых девять!\r\n\r\nВся семья и слуги застыли в оцепенении. И тут её облик затрепетал, как мираж в знойный день, и перед ними предстала её истинная суть — величественная девятихвостая лиса, в глазах которой светились и любовь, и стыд, и бесконечная печаль.\r\n\r\n«Прости меня, мой возлюбленный Киёмару, — сказала она человеческим голосом, но уже с лисьим акцентом. — Я — кицунэ. Я полюбила тебя и хотела лишь сделать тебя счастливым. Мои хвосты — это воплощение моей мудрости и силы, которую я обратила на благополучие твоего дома. Но теперь, когда тайна раскрыта, я не могу остаться».\r\n\r\nИ прежде чем кто-либо успел что-то сказать, она превратилась в сияющий шар света и унеслась прочь, в сторону священной горы Инари, покровительницы лис.\r\n\r\nКиёмару впал в отчаяние. Его удача покинула его так же быстро, как и жена. Но их дети, полукровки, унаследовали часть лисьей магии. Говорят, их потомки до сих пор живут среди людей, обладая даром предвидения и необъяснимой удачей.\r\n\r\nНо не все истории о Кицунэ так романтичны.\r\n\r\nА теперь представь другую. Бедный, но добрый крестьянин однажды зимним вечером нашёл в своих силках не зайца, а маленького лисёнка с белым кончиком хвоста. Вместо того чтобы убить его, он пожалел зверька и отпустил. На следующее утро к его хижине пришла незнакомая старуха.\r\n\r\n«Спасибо тебе за милосердие, — сказала она. — Ты отпустил моего внука. В знак благодарности хочу дать тебе совет: не женись на красивой незнакомке с родинкой на шее».\r\n\r\nКрестьянин удивился, но запомнил это. Прошло время, и он встретил как раз такую женщину — невероятно красивую, умную, которая сама предложила ему выйти замуж. Но он, вспомнив предупреждение, вежливо отказал.\r\n\r\nТой же ночью ему явился во сне старый лис.\r\n«Это была моя дочь, — сказал он. — Она хотела испытать тебя. Ты прошёл испытание. С этого дня я буду охранять твои поля. Ни один вор или злой дух не посмеет к ним приблизиться».\r\n\r\nИ так и случилось. Поля крестьянина всегда давали самый богатый урожай, а его семья никогда не знала нужды.\r\n\r\nВот такие они, Кицунэ. Они могут быть благодарными покровителями, как лис с горы Инари. Могут быть верными жёнами и мужьями, чья любовь сильнее видовых различий. А могут — и это тоже важно — быть злыми обманщиками, «ногицунэ», которые морочат голову путникам, насылают болезни и разоряют деревни, просто ради забавы.', 'Фольклорный сборник'),
('JP009', 'Kyokotsu', 'Старый, заброшенный колодец где-нибудь на окраине деревни. Глубокий, с каменными стенками, поросшими мхом. Вода в нём давно почернела от времени и ила, и оттуда всегда веет запахом сырости и тления. Местные дети боятся подходить к нему близко, а старики качают головами, приговаривая: «Не заглядывай туда, а то он тебя утащит».\r\n\r\n«Он» — это Кёкотцу.\r\n\r\nВ отличие от многих духов, у Кёкотцу редко есть имя или сложная предыстория. Он — сама смерть, застрявшая на полпути между мирами. Само его имя говорит за себя: «Кё» (狂) — «безумный, одержимый», «Котцу» (骨) — «кость, скелет». Безумный скелет.\r\n\r\nКак он появился? Версий множество, и все они сводятся к насильственной и несчастной смерти.\r\n\r\nОдна из самых распространенных историй гласит, что это дух человека, который упал в этот самый колодец, захлебнулся и утонул. Его тело так и не нашли, не предали земле по правильному обряду, и его душа, полная ярости и обиды на живых, не смогла переродиться. Она осталась в колодце, сросшись с ним, и со временем плоть истлела, обнажив кости, пропитанные злобой.\r\n\r\nДругая версия, ещё более мрачная, рассказывает о преступлении. Может, это был путник, которого ограбили и сбросили в колодец, чтобы скрыть следы. А может, это несчастный муж, которого в колодец столкнула его же неверная жена с любовником. Его последние мгновения были наполнены ужасом, предательством и осознанием собственной жуткой участи. Эта смесь эмоций и создала Кёкотцу.\r\n\r\nТак или иначе, теперь он там, внизу. Он не просто призрак. Он — часть колодца. Его скелет может быть неестественно большим, а кости — почерневшими от времени и ила. Но самое жуткое — это его поведение. Он не молчалив, как Сукима-онна. Его безумие находит выход в звуках.\r\n\r\nЕсли ты, несмотря на запреты, подойдёшь к краю колодца и заглянешь вниз, в чёрную воду, ты не увидишь своего отражения. Вместо этого из глубины доносится тихий, булькающий, будто сквозь воду, смех. Это не весёлый смех, а полный безумия и отчаяния хохот, от которого кровь стынет в жилах.\r\n\r\nА потом… ты увидишь, как что-то белеет в темноте. Это его костяная рука медленно показывается из воды и хватается за скользкий край колодца. Потом вторая. И вот он, скелет, с бешено горящими в пустых глазницах огоньками, начинает медленно, с треском суставов, вылезать наружу.\r\n\r\nЕго цель — не просто напугать. Он хочет компании. Он хочет, чтобы кто-то разделил его вечное одиночество в ледяной, тёмной воде. Его костлявые пальцы тянутся к тебе, чтобы схватить и утянуть в свою могилу.\r\n\r\nГоворят, если ты услышал его смех — уже поздно бежать. Он уже заметил тебя. Единственный шанс — это никогда не проявлять к нему интереса. Не заглядывать в старые колодцы, не прислушиваться к подозрительным звукам из них, не бросать в них камни.', 'Школьный слух'),
('JP010', 'Jikininki', 'Жил-был в одной горной деревне монах. Будем звать его Мусо. Он был не святой, а просто человек, стремящийся к просветлению. Однажды он забрёл в далёкую, незнакомую долину и, не найдя другого пристанища, решил переночевать в маленькой, заброшенной хижине отшельника.\r\n\r\nНочью его разбудил шорох. В хижину вошла фигура. Это не был ни человек, ни животное. Это было нечто, напоминающее разлагающийся труп, но движущееся с ужасающей, механической целеустремленностью. От него исходил смрад тления. Существо подошло к телу недавно умершего старика, которое лежало в углу хижины (Мусо не заметил его в темноте), и своими длинными, костлявыми руками начало… пожирать его.\r\n\r\nМусо застыл в ужасе, не в силах пошевелиться. Он читал молитвы, но они не оказывали на существо никакого действия. Насытившись, чудовище повернулось к нему. Его глаза были полны не злобы, а бездонной, вселенской скорби. И оно исчезло.\r\n\r\nНа следующее утро потрясенный Мусо отправился в ближайшую деревню, чтобы найти священника и рассказать о кошмаре. К его удивлению, местный старейшина лишь горько вздохнул.\r\n\r\n«Ты видел Каммёсина-сма, нашего бывшего священника, — сказал старик. — Он был добрым и набожным человеком. Но в его сердце, сам того не ведая, таилась одна тёмная черта — жадность. Не жадность к деньгам, а жадность к духовным заслугам, гордыня. Он тайно гордился своей святостью. Когда он умер, его душа не смогла обрести покой. Карма, порожденная этой гордыней, превратила его в Дзикинники».\r\n\r\nИ старейшина объяснил Мусо суть этого ужасного проклятия. Дзикинники — это не демоны по своей природе. Это души умерших людей, которые при жизни были эгоистичны, жадны или, как священник, полны духовной гордыни. В наказание они перерождаются в состоянии вечного голода, который невозможно утолить. Но голод этот — не за едой. Их пища — плоть умерших соплеменников.\r\n\r\nВот его проклятие:\r\n\r\nВечный Голод: Они вынуждены пожирать человеческую плоть, испытывая при этом непрекращающееся отвращение к себе и своей природе. Они не хотят этого делать, но не могут остановиться.\r\n\r\nПолное Осознание: В отличие от многих других призраков, Дзикинники полностью осознают, кем они были и во что превратились. Они помнят свою прошлую жизнь, свою семью, своих друзей. И теперь они вынуждены осквернять и пожирать тела тех, кого когда-то знали.\r\n\r\nНевидимость: Для обычных людей они невидимы. Живые видят лишь то, как трупы сами по себе исчезают или оказываются обглоданы. Дзикинники действуют в полной изоляции, невидимые и неприкаянные.\r\n\r\nБессилие перед Молитвой: Молитвы и священные обряды не могут изгнать или уничтожить их. Они — не злые духи, которых можно экзорцировать, а воплощение кармического наказания. Их участь — нести своё бремя, пока не исчерпается плохая карма, что может занять многие века.\r\n\r\nТот Дзикинники, которого видел Мусо, приходил к телу того самого старика, которого он знал при жизни. Он делал это не со зла, а потому, что был вынужден. Его глаза, полные скорби, говорили о большем страдании, чем мог бы испытать любой другой призрак.\r\n\r\nС тех пор Мусо понял: самые страшные монстры — это не те, что приходят извне, а те, что рождаются из изъянов человеческой души. Дзикинники — это вечное напоминание о том, что даже незначительный грех, оставленный без внимания, может привести к чудовищным последствиям в следующей жизни. Они бродят в вечной тьме, в одиночестве исполняя свою ужасную долю, неспособные cry о помощи, неспособные обрести покой, обречённые пожирать то, что они когда-то любили.', 'Школьный слух'),
('JP011', 'Hachishaku-sama', 'Мальчик по имени Кендзи (Kenji) приезжает в деревню в регионе Тохоку к бабушке и дедушке на летние каникулы. Там он замечает странную высокую женщину в белом платье и соломенной шляпе (как у крестьянки), которая стоит вдалеке и смотрит на него. Она около 2,4 метров ростом (восемь сяку — старая японская мера), с длинными чёрными волосами, бледной кожей и... голосом, который то женский и соблазнительный, то низкий, мужской. Она повторяет \"Po... Po... Po...\" — как будто зовёт или насмехается. Поначалу Кендзи думает, что это соседка, но бабушка бледнеет и шепчет: \"Это Хачишаку-сама. Она крадёт детей, которым 9–11 лет. Тебе 11, так что беги, пока можешь!\"\nЖенщина начинает преследовать его: появляется у окна, стучит в стекло, подражает голосам родителей по телефону, чтобы заманить. Деревенские жители знают легенду — она выбирает \"любимого\" ребёнка и забирает его навсегда, превращая в... ну, лучше не спойлерить. Чтобы спастись, дедушка устраивает ритуал: строит алтарь с пятью статуями Дзидзо (буддийские стражи детей), ставит их по углам дома и читает сутры. Это якобы запирает её в деревне. Кендзи держится внутри дома несколько дней, слыша, как она бродит снаружи, повторяя \"Po... Po...\" и пытаясь войти. В конце ритуал срабатывает, она отступает, и семья отправляет Кендзи назад в Токио.\nНо эпиграф — это punchline: годы спустя, уже взрослый Кендзи живёт в городе, и вдруг звонит бабушка: \"Одна из статуй Дзидзо сломана... та, что смотрит в сторону твоего дома\". И на том конце линии слышен знакомый голос: \"Po... Po... Po...\"', 'Интернет фольклор'),
('JP012', 'Jorogumo', 'Давным-давно у водопада Дзёрен жил дровосек по имени Таро.\nОднажды он рубил дрова и увидел, как из тумана вышла прекрасная женщина в кимоно цвета заката.\nОна играла на бива мелодию, от которой сердце замирало.\n— «Ты устал, — сказала она. — Приляг, я спою тебе колыбельную».\nТаро подошёл ближе… и вдруг паутина обвила его ноги.\nЖенщина рассмеялась — и превратилась в огромного паука с глазами, как угли.\n— «Ты будешь моим ужином!» — прошипела она.\nНо тут из воды вынырнул дух водопада (водяной ками).\nОн ударил струёй — паучиха зашипела, отпустила Таро и убежала в пещеру.\nС тех пор у водопада ставят синтоистские ворота (тории) и подносят рис, чтобы Джорогу́мо не возвращалась.\nА если услышишь бива у воды — беги, не оглядывайся.', 'Фольклорный сборник'),
('JP013', 'Yuki-onna', 'Давным-давно, в деревне на краю заснеженных гор Хоккайдо, жили два дровосека: молодой Минакити и старый Мосаку.\nКаждое утро они уходили в лес рубить дрова, а к вечеру возвращались с вязанками за спиной.\n\nОднажды разыгралась страшная метель.\nСнег валил стеной, ветер выл, как волк.\nДровосеки укрылись в старой хижине у реки — без огня, без еды, только друг у друга.\n\nНочью Минакити проснулся от холода, который проникал в кости.\nДверь хижины была открыта, и в проёме стояла женщина в белом.\nЕё кожа была белее снега, волосы — чёрные, как ночь, глаза — два куска льда.\nОна не шла — скользила, не оставляя следов.\n\nЖенщина подошла к Мосаку.\nДыхнула на него — и старик замёрз мгновенно, как статуя изо льда.\nПотом повернулась к Минакити.\n\n— Ты молод и красив, — прошептала она голосом, похожим на треск льда.\n— Я пощажу тебя. Но если когда-нибудь расскажешь о том, что видел, я вернусь и заморожу твоё сердце.\n\nИ исчезла, как дым.\n\nГоды спустя\nМинакити вырос, женился на девушке по имени О-Юки — тихой, бледной, с глазами цвета зимнего неба.\nУ них родились дети.\nО-Юки никогда не мёрзла, даже в самые лютые морозы.\nОна любила сидеть у окна и смотреть на снег.\nОднажды вечером, когда дети спали, Минакити рассказывал жене старую историю:\n\n— Когда я был молод, в метель… я встретил Юки-онну, снежную женщину. Она убила моего учителя, но пощадила меня…\n\nО-Юки замерла.\nЕё лицо стало ещё бледнее.\nГлаза — два куска льда.\n\n— Это была я, — сказала она голосом, от которого в комнате похолодало.\n— Ты нарушил обещание.\n\nВ тот же миг О-Юки растаяла в облаке снега.\nИз окна подул ледяной ветер.\nДети проснулись — мама исчезла.\nНа полу остался только кусок льда в форме женского лица.', 'Фольклорный сборник'),
('JP014', 'Nekomata', 'Давным-давно, в деревне у подножия горы Фудзи, жила старушка О-Баа — ведьма, что умела говорить с кошками.\nУ неё была любимая чёрная кошка Куро — с глазами цвета янтаря и хвостом, как у лисицы.\nКуро была умна: ловила мышей, приносила травы для зелий и даже пела по ночам.\n\nКогда О-Баа умерла, Куро осталась одна.\nОна бродила по деревне, и люди кормили её рисом, но не любили — боялись чёрной шерсти и странных глаз.\n\nПрошло девять лет.\nКуро стала старой, но не умирала.\nКаждую весну она исчезала в лесу, а осенью возвращалась — моложе, чем была.\n\nНа девятую осень случилось странное:\nКуро выросла до размера тигра.\nХвост раздвоился, как у кицунэ.\nГлаза горели красным.\nОна заговорила человеческим голосом:\n\n— Я — Неко-мата.\nДевять раз я умирала и возрождалась.\nТеперь я хозяйка ночей.', 'Книга сказок для детей'),
('JP015', 'Akaname', 'Давным-давно, в горах префектуры Ямагата, где пар от горячих источников клубится как призраки, стоял заброшенный онсэн — общественная баня.\nЕё владелец, старик Исаму, после смерти жены впал в тоску. Он перестал чистить ванны, подметать полы, мыть стены. Вода в бассейнах покрылась плесенью, а углы заполнились чёрной грязью, волосами и паутиной.\n«Зачем? — бормотал Исаму. — Никто не приходит. Всё равно».\nНочи напролёт он сидел у очага, а баня темнела, как могила.\n\nОднажды в лунную ночь, когда туман стелился по полу, как живое существо, Исаму услышал шуршание.\nИз-за угла ванны выскользнула тень — маленький гоблин, ростом с ребёнка, с кожей красной, как ржавчина, и головой, покрытой булыжниками.\nЕго глаза горели жёлтым, а изо рта высовывался длинный, скользкий язык, как у змеи.\nЭто был Аканамэ — Облизыватель грязи.\n\nАканамэ не рычал и не пугал. Он просто полз на четвереньках, принюхиваясь к плесени.\nЯзык его выстрелил вперёд — и начал лизать!\nЧавк! — стенка ванны заблестела.\nШлёп! — грязь с пола исчезла, как по волшебству.\nИсаму замер в ужасе: «Что ты такое, чудовище?»\nНо Аканамэ не ответил. Он только хихикнул — голосом, похожим на бульканье воды в трубе, — и продолжил пир: слизывал сало, плесень, волосы, всё, что накопилось за годы забвения.\n\nНаутро Исаму проснулся от... тишины.\nБаня сияла! Ванна чистая, как слеза, полы — зеркальные, даже воздух пах соснами.\n«Может, сон?» — подумал старик. Но углы были вылизаны до блеска, а на стене осталась царапина — след от когтей.\nС тех пор Аканамэ приходил каждую ночь.\nИсаму сначала прятался, потом стал смотреть.\nГоблин работал неустанно: лизал, чавкал, полировал.\nОднажды, набравшись смелости, Исаму спросил:\n\n— Почему ты помогаешь? Ты же ёкай, демон!\n\nАканамэ остановился, язык его дёрнулся, как хвост.\n\n— Я — страж чистоты, — прошептал он голосом, полным эха.\n— Грязь рождает тьму: болезни, злых духов, одиночество.\nЯ ем её, чтобы мир не утонул в гнили.\nНо если хозяин сам не берётся за дело... я уйду. И вернусь — с голодом.\n\nИсаму понял.\nОн взял щётку и ведро. Вместе с Аканамэ — один чистил, другой лизал — они вернули онсэн к жизни.\nДеревня узнала: баня снова открыта, вода горячая, пар целебный.\nЛюди приходили толпами, смех эхом разносился по горам.\nНо однажды Исаму увидел в зеркале отражение: Аканамэ стоял за ним, улыбаясь.\nЯзык его блеснул — и исчез.\nС тех пор гоблин больше не приходил.\nА Исаму рассказывал гостям:', 'Фольклорный сборник'),
('JP016', 'Gashadokuro', 'В эпоху Сэнгоку, в деревне у реки Кисо, шла война.\nСолдаты сожгли поля, угнали скот.\nЖители умирали от голода — один за другим.\nИх не хоронили — не было сил.\nКости лежали в полях, как белые камни.\n\nОднажды ночью выжившие услышали громкий стук:\nГаша! Гаша! Гаша!\nИз тумана вышел скелет выше сосен.\nЧереп — как луна, глаза — два красных угля.\nОн не рычал — просто смотрел.\n\n— Мы голодны, — прошептал он голосом тысячи мёртвых.\n— Теперь ты будешь нашим ужином.\n\nОн схватил старосту — хрусть! — голова оторвалась, как яблоко.\nКровь хлынула в пустые рёбра скелета.\nДеревня кричала, но некому было бежать.\nМаленькая девочка Аки спряталась в храме.\nОна вспомнила слова бабушки:\n\n«Гашадокуро боится света памяти».\n\nАки зажгла сто свечей — по одной за каждого умершего.\nНазвала имена.\nСкелет замер.\nСвечи вспыхнули ярче — и кости рассыпались в пепел.\n\nУтром в поле выросли цветы лотоса.\nАки стала жрицей.\nС тех пор в деревне никто не умирал голодным.', 'Фольклорный сборник'),
('JP017', 'Rokurokubi', 'В старом Киото жил фонарщик Таро, что каждую ночь зажигал бумажные фонари на улицах Гион.\nОднажды он женился на тихой девушке О-Хана — бледной, с длинной шеей и глазами, как у лани.\nДнём она была идеальной женой: варила рис, стирала кимоно, улыбалась.\nНо по ночам... Таро просыпался от скрипа.\n\nОднажды он притворился спящим.\nВ полночь О-Хана встала.\nЕё шея вытянулась на три метра, как змея, и голова выскользнула в окно.\nОна парила над улицами, освещённая луной, и пила свет из фонарей — один за другим гасли.\nТаро в ужасе схватил нож, но... пожалел.\n\n«Она не вредит, — подумал он. — Просто голодна по свету».\n\nНаутро он спросил:\n\n— Почему ты гасишь мои фонари?\nО-Хана заплакала:\n— Я — рокурокуби. Проклята за то, что в прошлой жизни завидовала чужому счастью.\nНочью я должна пить свет, иначе сгорю.\nНо я люблю тебя... и не хочу пугать.\n\nТаро не прогнал её.\nВместо этого он сделал особый фонарь — из светлячков и бумаги, что светил только для неё.\nКаждую ночь он ставил его у окна.\nГолова О-Ханы прилетала, пила свет и возвращалась, не туша уличные фонари.\nС тех пор в Гионе говорят:\n\nЕсли видишь один горящий фонарь в пустом переулке — это дар рокурокуби.\nНе гаси его — и она не тронет теб', 'Фольклорный сборник'),
('JP018', 'Bakekujira', 'В рыбацкой деревне Кусакабэ, у моря Внутреннего Японского, жил старый рыбак Гэндзи.\nОн хвастался: «Я поймал самого большого тунца в провинции!»\nНо однажды в сеть попал детёныш кита — белый, как снег.\nГэндзи не отпустил: «Мясо дорогое!» — и убил его гарпуном.\n\nТой ночью море почернело.\nВолны ревели, как раненый зверь.\nИз пены поднялся гигантский скелет кита, кости светились зелёным, глаза — два фонаря.\nРот его был открыт, как пещера.\nБакэкудзира.\n\n— Ты убил моего ребёнка, — прогремел голос, от которого чайки падали мёртвыми.\n— Теперь я проглочу твою луну.\n\nКит вдохнул — и луна исчезла с неба.\nТьма упала на деревню.\nРыба исчезла из сетей.\nДети заболели.\nГэндзи понял: это проклятие.\nОн вышел на берег с гарпуном в руке и крикнул:\n\n— Возьми меня вместо луны!\n\nБакэкудзира рассмеялся костями.\n\n— Слишком поздно.\nНо я дам шанс: верни мне кость ребёнка.\n\nГэндзи нырнул в море, нашёл маленький скелет детёныша на дне.\nПоложил его в лодку, поджёг — и пустил по волнам.\nПламя осветило кости Бакэкудзиры.\nТот растворился в свете, вернув луну на небо.\nС тех пор рыбаки не трогают китов.', 'Книга сказок для детей'),
('JP019', 'Ikiryo', 'В древнем Киото, при дворе императора, жила леди Рокудзё — вдова, умная и гордая.\nЕё полюбил принц Гэндзи, но он увлёкся молодой Аои-но-уэ.\nРевность Рокудзё сожгла её сердце.\n\nНочью, когда Гэндзи спал с Аои, в покоях появился туман.\nИз тумана вышла леди Рокудзё — но не телом, а душой: бледная, с горящими глазами, волосы развевались, как дым.\nОна ударила Аои невидимой рукой — та упала в обморок.\nКаждую ночь икирё возвращалась: душила, била, шептала проклятия.\n\nМонахи читали сутры, ставили амулеты — ничего не помогало.\nАои слабела, пока не умерла.\n\nГэндзи понял: это Рокудзё.\nОн пришёл к ней, умолял простить.\nРокудзё расплакалась — и в тот миг её икирё растаяла, как утренний туман.\nНо Аои уже не вернулась.', 'Фольклорный сборник'),
('JP020', 'Oiwa', 'В старом Эдо, в квартале Ёцуя, жил самурай Иэмон — красивый, но жадный.\nЕго жена Оива родила дочь, но после родов осунулась.\nИэмон влюбился в богатую О-Умэ и решил: «Оиву — прочь».\n\nОн купил яд у знахарки и подмешал в чай.\nОива выпила — и лицо её распухло, один глаз вытек, кожа покрылась язвами.\n\n— За что, муж мой? — прошептала она и умерла, вцепившись в подол его кимоно.\n\nИэмон женился на О-Умэ.\nВ свадебную ночь невеста посмотрела в зеркало — и увидела не себя, а Оиву:\n\n— Ты украла мою жизнь, — прошипело отражение.\nО-Умэ закричала, схватила меч — и отрубила себе голову, приняв её за голову Оивы.\n\nИэмон бежал в храм.\nТам в колоколе увидел лицо Оивы.\nКолокол упал — раздавил его.\nС тех пор в Ёцуя каждую ночь слышен плач женщины и звон разбитого зеркала.', 'Школьный слух'),
('JP021', 'Hone-onna', 'Кратко о Хонэ-онна\nХонэ-онна (骨女, «Женщина-скелет») — ёкай из периода Эдо.\nСнаружи — красивая женщина, часто в кимоно, с бледной кожей и томным взглядом.\nВнутри — скелет, обтянутый тонкой плёнкой плоти.\nПоявляется ночью, соблазняет мужчин, высасывает душу через поцелуй или объятие, оставляя высохший труп.\nМотив: ревность, предательство, месть (часто — дух любовницы, убитой мужем).\nИзображена у Торияма Сэкиэн в «Хяку моногатари» (1781).\n\nСказка «Хонэ-онна и чайный домик»\n\nВ Киото, у реки Камо, стоял чайный домик «Цветущая слива».\nЕго хозяйка О-Хана была так красива, что самураи дрались за право пить чай из её рук.\nНо один купец, Такэси, влюбился по-настоящему.\nОн подарил ей золотой гребень и обещал жениться.\n\nТакэси лгал.\nУ него была жена и дети в Осаке.\nКогда правда всплыла, О-Хана повесилась на том самом гребне в саду.\n\nНа следующую ночь Такэси вернулся в чайный домик — «проститься».\nО-Хана встретила его в кимоно цвета крови.\n— Ты пришёл, — прошептала она.\n— Я ждала.\n\nОни пили сакэ при свечах.\nТакэси обнял её — и рука прошла насквозь.\nКимоно упало.\nПод ним — скелет с горящими глазами.\n\n— Ты предал меня, — сказала Хонэ-онна.\n— Теперь твоя плоть — моя.\n\nОна поцеловала его.\nТакэси высох за миг: кожа сморщилась, глаза ввалились, остался только скелет в кимоно.\nНаутро слуги нашли два скелета, обнявшихся у чайного столика.\nС тех пор в «Цветущей сливе» не зажигают свечи.', 'Фольклорный сборник');
INSERT INTO `story` (`id`, `name`, `story`, `source`) VALUES
('JP022', 'Ubume', 'В Киото, у старого моста через реку Камо, каждую осень туман стелился густо, как молоко.\nТам, в полночь, появлялась женщина в белом кимоно, с мокрыми волосами до пояса.\nНа руках — свёрток, из которого доносился плач.\n\nОднажды шёл по мосту торговец Сабуро.\nУвидел женщину — бледную, как луна.\nОна поклонилась:\n\n— Господин, подержите моего сына. Я устала.\nСабуро взял свёрток — тёплый, лёгкий.\nЖенщина шагнула в туман и исчезла.\n\nСвёрток вдруг потяжелел — как камень.\nПотом — как бочка риса.\nПотом — как бык.\nСабуро упал на колени, руки дрожали.\nРебёнок заплакал громче — голосом ста женщин.\n\n— Отпусти! — крикнул Сабуро.\n— Не могу, — ответил свёрток. — Ты взял — ты отец.\n\nТут из тумана вышел монах из храма Хигаси Хонган-дзи.\nОн ударил посохом по мосту и крикнул:\n\n— Убу́мэ! Отпусти душу!\nМонах бросил Сабуро рисовый колобок (охаги).\n\nСабуро сунул колобок в свёрток.\nВ тот же миг тяжесть исчезла.\nСвёрток стал пустым кимоно, а из реки донёсся вздох:\n\n— Спасибо… теперь я могу упокоиться.\n\nНа мосту остались только сладости и мокрые следы босых ног.', 'Фольклорный сборник'),
('JP023', 'Futakuchi-onna', '\nFutakuchi-onna — «Женщина с двумя ртами».\n\nВнешность: обычная красивая женщина, но на затылке — второй рот с зубами и языком.\nПроисхождение: проклятие за скупость или жестокость к еде/детям.\nЧерта: задний рот жрёт бесконечно, шепчет проклятия и дергает волосы, как змеи.\nИсточник: Торияма Сэкиэн, «Эхон хяку моногатари» (1677).\n\n\nСказка «Голодная мачеха»\n\nВ деревне у реки жил старик Горо с дочкой Хана.\nЖена умерла, и он женился на О-Яэ — красавице с длинными чёрными волосами.\nО-Яэ улыбалась Горо, но ненавидела Хану.\nДевочке давала рисовую шелуху, себе — жирную рыбу.\n\nОднажды ночью Хана проснулась от шуршания.\nИз-под волос О-Яэ высунулся второй рот — с клыками, как у волка.\nОн шептал:\n\n«Го-ло-о-од-но… Еды… Еды-ы-ы!»\nИ пожирал рис из кладовой, пока волосы не извивались, как щупальца.\n\nУтром кладовая пуста.\nГоро удивился, но О-Яэ сказала:\n\n— Мыши съели.\nА Хане дала ещё меньше.\n\nНа третью ночь второй рот заговорил громко:\n\n— Дай ребёнка!\nО-Яэ схватила Хану, но девочка вырвалась и побежала к реке.\nТам стоял старый ками реки — в образе черепахи.\nОн дал Хане рисовый колосок и сказал:\n— Положи в рот мачехе.\n\nХана вернулась, притворилась спящей.\nКогда О-Яэ наклонилась, девочка всунула колосок в задний рот.\nРот захлебнулись, волосы завязались узлом, и О-Яэ превратилась в дерево — с двумя дуплами вместо ртов.\nС тех пор дерево даёт рис всем голодным детям деревни.', 'Фольклорный сборник'),
('JP024', 'Raiju', 'В деревне у озера Бива жил мальчик Тэцу, который боялся гроз.\nКогда небо гремело, он прятался под одеяло и считал вспышки.\n\nОднажды летней ночью ударил гром — бум!\nТэцу выскочил во двор, забыв страх.\nМолния ударила в сосну — и из неё выпал зверёк:\nголубая шерсть искрит, глаза — как лампочки, хвост — молния.\nЭто был Raijū.\n\n— Ты звал меня? — прогремел он голосом Райдзина.\n— Нет! — пискнул Тэцу.\n— Тогда спи. Я люблю тёплые пупки.\n\nМальчик побежал домой, но Raijū влетел в окно и свернулся клубочком на животе.\nТэцу чувствовал: внутри жжёт, как будто молния ищет выход.\nМама вспомнила старую присказку:\n\n«Ладан на пупок — Raijū уйдёт в облак».\nОна зажгла ароматическую палочку, положила на пупок.\nRaijū чихнул искрами, вылетел в окно и растворился в грозовом небе.\n\nС тех пор Тэцу спал с ладаном на животе.\nА когда гремело — кричал:\n\n«Каминари! Уходи!»\nИ молния обходила дом стороной.', 'Книга сказок для детей'),
('JP025', 'Zashiki warashi', 'В деревне Иватэ стоял старый дом семьи Сато.\nКрыша текла, полы скрипели, а в кладовой не было ни риса, ни соли.\nХозяин, Таро, собирался продать дом и уехать в город.\n\nОднажды ночью он услышал смех из гостиной.\n\nЗаглянул — на татами сидела девочка в красном кимоно, играла в куклы.\n— Кто ты? — спросил Таро.\n— Я Zashiki-warashi, — ответила она, не поднимая глаз.\n— Уходи, дом пустой, — вздохнул Таро.\n— Пока я здесь — не пустой, — улыбнулась девочка и исчезла.\n\nНаутро Таро нашёл мешок риса у порога.\nЧерез неделю — монеты в ящике.\nЧерез месяц — покупатели толпами: «Купим дом, но только с девочкой!»\nТаро понял: удача вернулась.\nНо однажды он рассердился — дети соседей разбили вазу.\n\n— Убирайтесь все, включая эту невидимку! — крикнул он.\n\nНочью смех смолк.\nУтром — пусто: рис пропал, монеты исчезли, крыша обвалилась.\nТаро уехал в город — нищим.\nА в деревне шепчут:\n\nZashiki-warashi ушла в другой дом.\nИщите смех — там будет богатство.', 'Книга сказок для детей'),
('JP026', 'Sugawara no Michizane', 'Не удалось найти сведения об истории или происхождении', '-'),
('JP027', 'Koma inu', '\nВ деревне у святилища Инари жил мальчик Хикару.\nКаждое утро он приносил риса двум каменным Кома-ину у ворот тории.\n«Спасибо, что охраняете нас», — говорил он.\nКаменные псы молчали, но однажды ночью...\n\nХикару проснулся от рычания.\nУ ворот святилища стоял чёрный демон с рогами, как у быка.\nОн хотел украсть священный колокольчик, чтобы вызвать бурю.\nКома-ину ожили.\n\nЛевый (с рогом) выдохнул свет — «Ааааа!» — и демон ослеп.\nПравый (без рога) захлопнул пасть — «Ун!» — и буря стихла.\n\nДемон взвыл и убежал в лес.\nА Кома-ину вернулись в камень.\nНаутро Хикару увидел:\n\nНа лапе левого пса — свежая царапина.\nНа зубах правого — кусочек рога демона.\n\nСказка «Кома-ину и мальчик с фонарём»\n\nВ деревне у святилища Инари жил мальчик Хикару.\nКаждое утро он приносил риса двум каменным Кома-ину у ворот тории.\n«Спасибо, что охраняете нас», — говорил он.\nКаменные псы молчали, но однажды ночью…\n\nХикару проснулся от рычания.\nУ ворот святилища стоял чёрный демон с рогами, как у быка.\nОн хотел украсть священный колокольчик, чтобы вызвать бурю.\nКома-ину ожили.\n\nЛевый (с рогом) выдохнул свет — «Ааааа!» — и демон ослеп.\nПравый (без рога) захлопнул пасть — «Ун!» — и буря стихла.\n\nДемон взвыл и убежал в лес.\nА Кома-ину вернулись в камень.\nНаутро Хикару увидел:\n\nНа лапе левого пса — свежая царапина.\nНа зубах правого — кусочек рога демона.', 'Книга сказок для детей'),
('JP028', 'Aka manto', 'Кратко про Ака Манто (赤マント)\nКто это: Юрэй в красном плаще, появляется только в школьных туалетах (чаще в женских).\nЧто делает: Спрашивает:\n\n— «Красный плащ или синий?»\n\n\nКрасный → режет горло, кровь льётся как плащ.\nСиний → душит до синевы.\nДругой ответ → убегает в канализацию, но может вернуться.\n\nСпасение: Сказать «Без плаща!» или бросить туалетную бумагу.\nПроисхождение: Городская легенда 1930-х, пик — 1980-е. Символ страха перед школьными туалетами.\n\nСказка «Ака Манто и девочка без имени»\n\nВ старой школе на окраине Осаки, где стены облупились, а лампочки мигали, как умирающие звёзды, ученики шептались:\n«Не ходи в туалет на третьем этаже после звонка».\n\nОднажды девочка Ая забыла тетрадь.\nВернулась в класс — темно.\nЗахотела в туалет.\nТолько третий этаж был открыт.\nВошла.\nКабинки пустые.\nВ зеркале — красный отблеск.\nГолос из последней кабинки, холодный, как лезвие:\n\n— «Красный плащ… или синий?»\n\nАя замерла.\nВспомнила слова старшеклассницы: «Скажи без плаща!»\n\n— Без плаого! — крикнула она.\n\nТишина.\nПотом шорох.\nИз кабинки выскользнул Ака Манто — высокий, в алом плаще, лицо скрыто капюшоном, глаза — два красных угля.\nОн рассмеялся — звук, как ржавые ножницы.\n\n— Умно, — прошипел он.\n— Но бумага кончилась.\n\nАя схватила рулон туалетной бумаги, что лежал у раковины, и швырнула в него.\nБумага развернулась в воздухе — белая лента.\nАка Манто зашипел, как кошка, и растворился в сливе унитаза, оставив только красную лужу, что быстро исчезла.\nАя выбежала.\nС тех пор в той школе всегда лежит запас бумаги в туалете.', 'Школьный слух'),
('JP029', 'Hitotsume kozо', 'В деревне у реки Камо жил мальчик Таро, который боялся темноты.\nКаждую зиму, когда солнце садилось рано, он бежал домой, зажимая уши от шорохов.\n\nОднажды в последний день года Таро нёс бабушке моти — рисовые колобки.\nДорога вела мимо старого храма, где никто не молился сто лет.\nВдруг из тени выскочил маленький монашек с одним глазом!\nГлаз был как луна, язык — как красный флаг.\n\n— МОТИ! — прогундосил Хитотсумэ-кодзо и высунул язык до пояса.\nТаро закричал и бросил один колобок.\nГлаз заморгал, язык втянулся, и ёкай съел моти за секунду.\n\n— Ещё! — потребовал он.\nТаро отдал второй.\nТретий.\nНо на четвёртый не хватило смелости.\nОн убежал, оставив корзинку.\nНаутро бабушка открыла дверь — а на пороге полная корзина моти, и сверху золотая монета.\nА на снегу — один след: маленький, круглый, с одним большим отпечатком глаза.\n\nС тех пор Таро не боялся темноты.', 'Фольклорный сборник'),
('JP030', 'Sadako Yamamura', 'Давным-давно, в тихой деревне на острове Осима, родилась девочка по имени Садако. Её мать, Шидзуко, видела будущее в воде и слышала шепот ветра, но люди звали её шарлатанкой. Когда Садако исполнилось восемь, Шидзуко утонула в вулкане от горя, а девочка осталась с отцом — доктором Икумой, который экспериментировал с её дарами: она гнула ложки взглядом и вызывала бури мыслями.\nСадако выросла одинокой, как тень. В 19 лет она сбежала в Токио, где танцевала в театре, скрывая силу под маской красоты. Но любовь к технику Хироси разбилась: он узнал о её \"монстре\" внутри и отвернулся. В ярости Садако создала \"запись\" — вихрь образов из её боли: колодец, кольцо огня, крик матери. Она спрятала её в старой хижине, а сама вернулась домой.\nОтец, боясь хаоса, заманил дочь к заброшенному колодцу. \"Ты — болезнь мира\", — прошептал он и столкнул её в бездну. Камни накрыли крышку, а Садако кричала в темноте: \"Я вернусь... через семь дней\". Годы тянулись, как волосы в воде, но ненависть питала её. Она жила в колодце, шепча проклятия теням.\nПрошли десятилетия. Хижина стала курортом, колодец — фундаментом кабины. Группа подростков нашла старую кассету в ящике. \"Смотрим? — хихикнула девчонка. — Городская легенда!\" Экран замигал: женщина ползёт по экрану, волосы — чёрная река, глаза — бездонные. Звонок в полночь: \"Семь дней...\"\nПервый умер в понедельник — сердце лопнуло, как кольцо. Второй — во вторник, задохнувшись в ванне. Девчонка, последняя, увидела сон: Садако тянет руку из телевизора, мокрые волосы липнут к лицу. \"Скопируй... или умри\". Она сделала копию, но поздно — на седьмой день зеркало треснуло, и из него вылезла она: бледная, с ухмылкой, скрытой прядями. \"Теперь ты — я\".\nС тех пор кассета бродит: смотрит — и ждёт. А в тихих ночах, у старых колодцев, слышен шёпот: \"Семь... дней...\"', 'Интернет фольклор'),
('JP031', 'Wani', 'Кратко о Wani (鰐)\nWani — дракон-крокодил из японской мифологии.\n\nВнешность: тело крокодила, чешуя как у дракона, рога, усы, может летать и вызывать дожди.\nПроисхождение: водный ками, родственник китайского lóng и корейского yong.\nСимвол: море, реки, защита, иногда — жертва богам.\nГлавный миф: в Кодзики бог Сусаноо побеждает Ямато-но-Ороти — огромного Wani с 8 головами, чтобы спасти девушку.\n\n\nКороткая сказка «Wani и морская принцесса»\n\nДавным-давно в заливе Сугару жил Wani-но-ками — огромный крокодил-дракон с бирюзовой чешуёй.\nОн охранял подводный дворец принцессы Тойотама-химэ, дочери морского царя Рюдзина.\n\nОднажды рыбак Хоори (бог охоты) потерял волшебный крючок брата.\nСпустился на дно моря — и увидел Тойотаму.\nОни полюбили друг друга.\nНо Wani-но-ками ревновал:\n\n— Человек не достоин принцессы! — прорычал он и ударил хвостом — волна поднялась до неба.\n\nХоори достал меч Кусанаги (подарок Сусаноо).\nWani превратился в дракона с одной головой, взлетел, вызвал дождь — но меч сверкнул, и чешуя посыпалась, как жемчуг.\nWani упал, раненый.\nТойотама вышла из дворца:\n\n— Прости его, любимый. Он защищал меня.\nОна коснулась Wani — раны зажили.\n\nWani стал другом Хоори.\nОн подарил молодожёнам жемчужину приливов — чтобы море всегда было спокойным.\nА сам превратился в остров посреди залива — до сих пор там стоит скала в форме крокодила.', 'Фольклорный сборник'),
('JP032', 'Nure-onna', 'У берега деревни Акамуро (преф. Кагосима) жил рыбак Гэндзи.\nКаждое утро он выходил в море, а вечером возвращался с уловом.\nОднажды в тумане он увидел женщину на скале.\nВолосы её были мокрые, как после дождя, платье прилипло к телу.\nОна держала младенца и плакала:\n\n— Помоги! Ребёнок тонет!\n\nГэндзи подплыл, протянул руку…\nНо младенец растворился в воде, а женщина схватила его за горло.\nЛицо её стало рыбьим, рот — присоской.\n— Ты — мой ужин, — прошипела она.\nГэндзи выхватил нож для рыбы и воткнул в глаз.\nНурэ-онна завизжала, отпустила — и нырнула в волны, оставляя кровавый след.\nС тех пор рыбаки сыпят соль на лодку перед выходом в море.\nА если услышишь плач ребёнка в тумане — греби к берегу.', 'Фольклорный сборник'),
('JP033', 'Osan gitsune', 'Давным-давно, в Тоттори, у места под названием Гарагара (ныне недалеко от города Тоттори), жил крестьянин по имени Ёсобэй. Он был простым дровосеком, но слышал слухи о лисе-оборотне, что заманивает путников в свою нору и пьёт их кровь под луной.\nОднажды вечером, возвращаясь с поля, Ёсобэй увидел у дороги прекрасную женщину в ярком кимоно, с волосами цвета воронова крыла и глазами, искрящимися, как звёзды. Она улыбнулась:\n— Устал, странник? Иди ко мне, я напою тебя сакэ и спою песню о любви.\nЁсобэй замер. Он знал: это Осан-гitsuнэ, ревнивая лисица, что разлучает влюблённых и крадёт сердца. Но вместо того чтобы бежать, он хитро улыбнулся:\n— О, прекрасная! Но сначала покажи свой дом — я боюсь, что ты меня обманешь.\nЖенщина повела его по тропинке в лес, болтая о столичных модницах и ревнуя к каждой тени. Вдруг Ёсобэй остановился у ручья:\n— Подожди, я разожгу костёр — холодно.\nОн чиркнул кремнем, и пламя вспыхнуло ярко. Осан взвизгнула — огонь, её злейший враг! Хвост её мелькнул под кимоно: пушистый, с тремя кончиками, как у старой кицунэ.\n— Ты знала, что я лиса? — прошипела она, отступая.\n— Знал, — ответил Ёсобэй. — И обещаю: если отпустишь меня, я никому не скажу. А если нет — сожгу твой дом.\nОсан рассмеялась — звонко, как колокольчик, но с ноткой злости:\n— Ладно, смертный. Но помни: если женишься, я вернусь и разлучу тебя с женой. Ревность — моя стихия!\nОна исчезла в вихре листьев, а Ёсобэй вернулся в деревню. Годы спустя, когда его внуки ехали в Игу и встретили юную девушку, спрашивающую о \"старом дровосеке\", они ответили: \"Ёсобэй в мире духов\". Девушка вздохнула: \"Страшно!\" — и убежала. А в Хиросиме, говорят, Осан до сих пор пугает путников, превращаясь в огненный шар или рычащего льва, но всегда с улыбкой модницы.', 'Фольклорный сборник'),
('JP034', 'Taira no Masakado', 'Не удалось найти сведения об истории или происхождении', '-'),
('JP035', 'Onikuma', 'Не удалось найти сведения об истории или происхождении', 'Школьный слух'),
('JP036', 'Funayurei', 'Давным-давно, в рыбацкой деревне на побережье Сэтонайкай (Внутреннее море Японии), жил старый рыбак по имени Дзиро. Каждую ночь он выходил в море на своей маленькой лодке, ловил рыбу и возвращался с рассветом.\nОднажды разыгрался шторм: волны били о борт, туман скрыл звёзды. Дзиро уже повернул к берегу, как вдруг из тумана выплыли тени — бледные фигуры в рваных одеждах, с лицами, белыми как соль. Это были Funayūrei, призраки утонувших.\nИх вожак, с глазами, как чёрные водовороты, протянул черпак:\n— Дай нам воды! Наши глотки сухи от соли моря!\nДзиро знал легенды: если нальёшь — вода хлынет бесконечно, лодка утонет. Если откажешь — они разобьют судно волнами.\n\n\nХитрый рыбак улыбнулся и сказал:\n— Конечно, друзья! Но мой черпак лучше — он никогда не пустеет!\nОн взял свой старый черпак с дыркой на дне (которым черпал воду из лодки) и подал им.\nFunayūrei начали черпать — но вода утекала сквозь дыру, не заливая лодку. Призраки завыли от ярости:\n— Обман! Ты перехитрил нас!\nТени растаяли в тумане, шторм утих. Дзиро вернулся домой с уловом и рассказал сыновьям: \"Никогда не бойтесь моря, но уважайте его духов\".', 'Фольклорный сборник'),
('JP037', 'Okuri inu', 'Не удалось найти сведения об истории или происхождении', 'Школьный слух'),
('JP038', 'Nuppeppо', 'Не удалось найти сведения об истории или происхождении', 'Школьный слух'),
('JP039', 'Baku', 'Не удалось найти сведения об истории или происхождении', '-'),
('JP040', 'Oni', 'Давным-давно старушка стирала у реки, и из воды выплыл персик.\nДома... — сказала она, — большой!\nДома разрезали — а внутри мальчик! Назвали Момотаро («Персиковый мальчик»).\n\nМомотаро вырос сильным и добрым.\nУслышал: на острове Они-гасима демоны грабят деревни.\nВзял три киби-данго (рисовые лепёшки) и пошёл.\nПо дороге:\n\nСобака: «Дай данго — пой Njду с тобой».\nОбезьяна: «Данго — и я твой».\nФазан: «Данго — полечу впереди».\n\nПриплыли на остров.\nВорота охранял красный Они с дубиной.\nФазан клюнул в глаз, обезьяна прыгнула на рога, собака вцепилась в ногу.\nМомотаро разрубил ворота мечом.\nВ тронном зале — Сютэн-додзи, царь демонов, пьяный от сакэ.\n\n— Кто посмел?! — зарычал он.\n— Я, Момотаро! Верни сокровища! — ответил мальчик.\n\nБитва!\nДубина Они — бум! — промахнулась.\nМеч Момотаро — свист! — отрубил рог.\nСютэн-додзи упал:\n\n— Пощади! Возьми всё!\n\nМомотаро забрал золото, рис, волшебный молоток удачи.\nВернулся героем.', 'Фольклорный сборник'),
('JP041', 'Nuribotoke', 'Давным-давно, в маленьком храме на окраине Киото, жил молодой монах по имени Такаши. Он был ленив: вместо молитв спал, вместо чистки алтаря — ел сладости. Буцудан — домашний алтарь с деревянной статуей Будды — стоял в углу, покрытый пылью и паутиной. Такаши иногда мазал его лаком, но небрежно, и статуя стала чёрной, как ночь, с трещинами, как старое дерево.\n\nОднажды в дождливую ночь, когда ветер стучал в ставни, Такаши услышал скрип.\nИз алтаря вылезла тень — Нуриботокэ.\nЕго тело блестело лаком, глаза выкатились, как шары, язык болтался, как у змеи, а из-под робы торчал рыбий хвост.\nОн не говорил — только хихикал, как трескающийся лак.\n\nНуриботокэ подполз к Такаши и облизнул его лицо — язык был холодным и липким, как смола.\n— Ты забыл меня, — прошептал он голосом, похожим на шелест страниц сутры.\n— Теперь я заберу твою лень!\n\nМонах в ужасе отпрянул. Нуриботокэ начал танцевать: кружился по комнате, разбрасывая лаковые капли, которые превращались в маленьких жуков. Они ползли по стенам, шепча: «Чисти! Молись! Чисти!»\nТакаши пытался бежать, но дверь заклинило — лак Нуриботокэ запечатал её.\nВсю ночь ёкай преследовал его: лизал полы, чтобы они блестели, и заставлял монаха мыть алтарь.\nНа рассвете, когда петухи запели, Нуриботокэ вздохнул:\n\n— Теперь ты помнишь. Но если забудешь снова — я вернусь с хвостом и глазами.\n\nИ растаял обратно в статую.\nТакаши с тех пор стал усердным: чистил алтарь каждый день, читал сутры до зари.', 'Фольклорный сборник'),
('JP042', 'Chоchin obake', 'Не удалось найти сведения об истории или происхождении', 'Школьные слухи'),
('JP043', 'Suppon no yurei', 'Не удалось найти сведения об истории или происхождении', '-'),
('JP044', 'Taka-onna', 'Давным-давно, в Эдо (старом Токио), в квартале Ёсивара — где фонари горели всю ночь, а куртизанки в ярких кимоно танцевали для богатых самураев, — жила простая девушка по имени О-Така.\nОна была высокой и худой, с лицом, которое никто не звал красивым. Мужчины обходили её стороной, а соседки шептались: \"Кто возьмёт такую в жёны? Она как палка!\"\nО-Така завидовала оиран — знаменитым красавицам квартала. Ночи напролёт она стояла у заборов, слушая смех и музыку, и мечтала: \"Если бы я могла заглянуть внутрь...\"\n\nОднажды, в дождливую ночь, О-Така заболела от холода и ревности.\nОна умерла одна, в своей крошечной хижине.\nНо дух её не ушёл. Вместо этого О-Така превратилась в Така-онну.\nТеперь она могла растягивать ноги, как резину, становясь выше крыш.\nЕё лицо оставалось обычным — бледным и грустным, — но глаза горели злобой.\n\nПервая жертва — молодой самурай Хироси.\nОн пришёл в Ёсивару с друзьями, выбрал самую красивую оиран по имени Юкико.\nОни смеялись наверху, в комнате второго этажа, когда вдруг... стук в окно.\nХироси выглянул — и увидел женское лицо, висящее в воздухе, на уровне глаз.\n\"Почему не меня? — прошептала Така-онна. — Я тоже хочу любви!\"\nСамурай закричал, оиран упала в обморок.\nНаутро Хироси заболел — его мучили кошмары о высокой тени.\n\nС тех пор Така-онна бродила по кварталам.\nОна заглядывала в окна, пугала влюблённых, шептала проклятия.\nКуртизанки вешали амулеты из бамбука, чтобы отогнать её, а мужчины шептали: \"Не смотри в окно ночью!\"\n\nНо однажды Така-онна встретила монаха Эннина.\nОн сидел в храме у Ёсивары и молился за заблудшие души.\nОна растянулась до неба, чтобы напугать его, но монах сказал:\n— Ревность — как цепь. Отпусти её, и станешь свободной.\nТака-онна заплакала — слёзы упали дождём.\nТело её сжалось, и она исчезла, шепнув: \"Я была О-Така... Теперь я ухожу\".', 'Фольклорный сборник'),
('JP045', 'Kowai', 'В период Эдо жил торговец по имени Горо — толстый, как бочка, с аппетитом, как у дракона. Он ел за троих: в тавернах забирал чужие миски удона, если те замешкаются, а дома прятал рис от жены. \"Еда — это жизнь!\" — хохотал он, набивая рот. Соседи шептались: \"Горо съест даже душу, если она вкусная\".\n\nОднажды Горо объелся так, что сердце не выдержало — и он умер за столом, с палочками в руках.\nНо дух его не ушёл. Привязанность к еде держала его на земле. Ночью Горо проснулся… но уже не человеком. Тело усохло, лицо вытянулось, как у лиса, глаза загорелись жёлтым голодом. Он стал Kowai — странным лисо-человеком.\n\nKowai бродил по улицам, нюхая воздух. \"Голод… вечный голод!\" — стонал он. Рыл мусорные кучи, жрал гнилые овощи, падаль с дорог. Увидев лавку с удоном, бросался на неё: опрокидывал котлы, лизал разлитый бульон, пугал торговцев. \"Дай еды! Всё моё!\" — рычал он, но сколько ни ел, брюхо оставалось пустым, как бездонная яма.\n\nСоседи в страхе запирали двери. Один монах из храма решил помочь: поставил алтарь с подношениями — миску риса и сутру о жадности.\n\n— Уйди, дух, — сказал монах. — Твоя еда — в другом мире. Отпусти привязанность!\n\nKowai подошёл, съел рис… и на миг насытился. Тело его растаяло в тумане, уходя наконец в загробный мир.', 'Фольклорный сборник'),
('JP046', 'Kama itachi', 'Не удалось найти сведения об истории или происхождении', 'Книга сказок для детей'),
('JP047', 'Onryо', 'Давным-давно, в замке Банчо в Эдо (ныне Токио), жила служанка по имени Окику — красивая и честная девушка. Она служила самураю Тэссану Аояме, который влюбился в неё. Но Окику отвергла его, потому что любила другого.\nРазгневанный самурай решил отомстить. У него была коллекция из десяти драгоценных фарфоровых тарелок — семейная реликвия. Он спрятал одну и обвинил Окику в краже.\n«Ты сломала тарелку! — кричал он. — За это — смерть!»\nОкику в панике пересчитывала тарелки снова и снова: «Одна... две... три... девять... десять?» Но одной не хватало. Она умоляла, но самурай не слушал. В ярости он зарубил её мечом и бросил тело в колодец замка.\n\nПосле смерти Окику стала онрё.\nНочью из колодца доносился её голос — тихий, как шёпот ветра:\n\n«Одна... две... три... четыре... пять... шесть... семь... восемь... девять...»\nИ никогда не досчитывала до десяти. Вместо этого раздавался пронзительный крик, от которого волосы вставали дыбом.\nЗамок наполнился ужасом: слуги болели, самурай видел видения — Окику с разрубленным телом, ползущую из колодца с мокрыми волосами. Его жена сошла с ума, дети умерли от лихорадки. Тэссан потерял всё: богатство, честь, разум.\n\nВ конце самурай пошёл к колодцу и крикнул:\n\n«Окику, прости! Вот твоя тарелка!» — и бросил недостающую.\nГолос ответил: «...десять!» — и затих.\nНо Окику не ушла. Она преследовала его до смерти, и замок опустел навсегда.', 'Фольклорный сборник'),
('JP048', 'Jinja hime', '\nДавным-давно, 8 апреля 1819 года, у побережья острова Хирадо в провинции Хидзэн (ныне префектура Нагасаки) рыбаки увидели странное существо, выплывшее из морских глубин. Это была jinja hime — длинная, змееподобная рыба с женским лицом, рогами на голове и чёрными волосами, развевающимися в воде. Её тело извивалось, как дракон, а глаза светились мудростью подводного мира.\nСущество заговорило человеческим голосом: \"Я — посланница великого Ryūjin, бога-дракона морей. Через семь лет по всей Японии разразится страшная болезнь под названием холера, и многие люди погибнут от неё. Но слушайте мой совет: нарисуйте мой облик и повесьте изображение в каждом доме. Оно отгонит болезнь, защитит от злых духов, и ваши потомки будут процветать в здоровье и удаче.\"\nРыбаки, дрожа от страха и благоговения, записали её слова, нарисовали портрет и распространили листовки по всей стране. Многие повесили изображения в домах, и, по преданиям, те, кто последовал совету, избежали эпидемии.', 'Фольклорный сборник'),
('JP049', 'Furi', 'Не удалось найти сведения об истории или происхождении', 'Фольклорный сборник'),
('JP050', 'Kasane', 'Давным-давно в деревне Ханю в провинции Симоса жил фермер Ёэмон с женой Осуги. У Осуги от предыдущего брака был сын Сукэ — уродливый, с изуродованным лицом и хромой ногой. Ёэмон ненавидел его и однажды, переходя мост через глубокую реку, столкнул Сукэ в воду. Мальчик утонул, не умея плавать.\nЧерез год у пары родилась дочь Руи, удивительно похожая на Сукэ. Селяне шептались, что это его дух вернулся, и прозвали её Касане (\"накапливающаяся\"). Родители умерли рано, оставив Касане одну. Она тяжело заболела, но странник Ягоро вылечил её. В благодарность Касане вышла за него замуж и передала отцовское имущество. Ягоро, однако, презирал её уродство.\nВскоре Ягоро устал от жены. Он заставил её нести тяжёлые мешки с бобами через реку и столкнул в бездну, утопив: наступил на грудь, набил рот песком и камнями, выколол глаза и задушил. Свидетели из деревни видели, но промолчали — \"из-за её уродства\".\nЯгоро жил в её доме, женился заново — но новая жена умерла внезапно. Так погибли пять жён подряд. Шестая родила дочь Кику, и они были счастливы, пока жена не умерла. Кику вышла за Кингоро, но в 13 лет заболела: из неё заговорил чужой голос: \"Я — Касане, твоя убитая жена! Я убила всех твоих жён за предательство!\" Дух обвинил Ягоро и селян в молчаливом соучастии, раскрывая старые грехи предков.\nДух требовал пышных поминок и каменного Будду. Когда селяне замешкались, Кику взлетела в воздух в ярости. Новости дошли до странствующего монаха Ютэна. Он молился сутрами, заставил Кику читать молитвы — и изгнал дух Касане. Но одержимость вернулась. Ютэн узнал о Сукэ и дал ему посмертное буддийское имя. Дух Сукэ ушёл в алтарь, и Кику исцелилась. Призраки Касане и Сукэ больше не беспокоили деревню.', 'Фольклорный сборник');
INSERT INTO `story_deity` (`id`, `story_name`, `story`) VALUES
('kami_S001', 'Amaterasu-Omikami', 'После того как бог Идзанаги вернулся из страны мёртвых Ёми, он совершил обряд очищения в водах реки.\nКогда он омыл левый глаз, из сияющего света родилась богиня — Аматэрасу Ōмиками, воплощение солнца и небесного порядка.\n\nИдзанаги увидел её свет и возрадовался.\nОн назвал её своей величайшей дочерью и сказал, что ей суждено править Такамагахара — Высокими Небесами.\n\nТак Аматэрасу стала владычицей неба, светом богов и источником порядка среди ками. Младший брат Аматэрасу, Сусаноо, был дик и неукротим.\nЕму была дарована власть над морями, но он отверг своё предназначение и стал сеять разрушение.'),
('kami_S002', 'Tsukuyomi-no-Mikoto', 'Во время того же обряда очищения Идзанаги, из его правого глаза родился Цукуёми — спокойный и сдержанный бог Луны. В отличие от своих брата и сестры, Цукуёми не стремился к власти и редко вмешивался в дела мира. Идзанаги назначил: Аматэрасу — править днём и Небесами, Цукуёми — управлять ночью и лунным циклом. Цукуёми стал воплощением: ритма времени, календаря, равновесия между светом и тьмой. По приказу Аматэрасу Цукуёми отправился к богине пищи Укэмоти-но-Ками. Во время пира он увидел, что еда создаётся из её тела — изо рта, носа и других частей. Считая это осквернением, Цукуёми убил богиню. Из её тела позже родились боги злаков, скота и урожая.Узнав о поступке брата, Аматэрасу пришла в ярость. Она объявила, что никогда больше не будет смотреть на Цукуёми. С этого момента: день и ночь перестали сосуществовать, солнце и луна начали следовать друг за другом. Так возник естественный цикл времени.  (Цукуёми один из самых загадочных ками, имеющий очень мало мифов, в историях, кодзиках и нихон-сёках действует редко и искать инфу про него было довольно трудно)'),
('kami_S003', 'Susanoo-no-Mikoto', 'Когда бог Идзанаги совершал обряд очищения после возвращения из страны мёртвых,\nиз его носа родился Сусаноо — могучий и неукротимый бог.\n\nЕму была дарована власть над морями и ветрами,\nно с самого начала он отличался бурным нравом и неумением следовать установленному порядку. Сусаноо не принял свою роль.\nОн беспрестанно плакал и бушевал, из-за чего:\n\nвысыхали реки,\n\nразрушались земли,\n\nнарушался покой ми. Идзанаги изгнал его, но перед уходом Сусаноо реш поднять Небеса,\nчтобы проститься со своей сестрой — Аматэрас. Вначале Сусаноо поклялся в чистоте своих намерений,\nи боги даже устроили ритуальное состязание, подтверждающее его искренность.\n\nОднако вскоре он вновь поддался своему хаосу:\n\nразрушал свящеые поля,\n\nосквернял хры, небесные ритуалы.\n\nКульминацией стало святотатство во время священного ткачества —\nпосле чего Аматэрасу скрылась в Небесной Каменной Пещере.\n\nИз-за действий Сусаноо м погрузил мир во тьму. На земле Идзумо Сусаноо сталкивается с восьмиглавым змеем Ямата-но-Ороти,\nкоторый пожирал дочерей одной семьи.\n\nОн побеждает чудовище хитростью и силой,\nа из его хвоста извлекает священный меч Кусанаги-но-Цуруги.\n\nЭтот меч позже станет одной из Императорских регалий Японии.'),
('kami_S004', 'Inari Okami', 'В давние времена, когда люди ещё напрямую ощущали присутствие ками, в одной горной деревне настал голод. Рисовые поля высохли, урожай погибал, и люди начали покидать свои дома. Однажды ночью к старому крестьянину явилась белая лиса. Она не говорила громко, но её голос звучал прямо в сердце. Она велела: \"Очисти поле, посей зёрна заново и принеси подношение Инари.\", Крестьянин подчинился. Он очистил землю, оставил рис и воду у небольшого святилища и каждый день благодарил ками. С первыми лучами солнца пошёл дождь. Рис поднялся, урожай оказался щедрым, и деревня была спасена. С тех пор на холме появилось святилище Инари, а белых лис стали считать посланниками божества. Инари не явилась в облике грома или света. Она проявилась через заботу, труд и благодарность.'),
('kami_S005', 'Izanagi-no-Mikoto', 'Когда Небо и Земля ещё не были оформлены, боги поручили Идзанаги и Идзанами создать сушу. Стоя на Небесном мосту, они погрузили священное копьё Аме-но-Нубоко в первозданный океан. Когда они подняли его, капли, упавшие с наконечника, образовали первый остров — Оногоро. На этом острове началось сотворение мира. Идзанаги и Идзанами соединились как супруги\r\nи начали рождать острова Японии и многочисленных ками: гор, рек, ветров, лесов. Но при рождении бога огня Кагуцути Идзанами была смертельно ранена. Идзанаги, не желая мириться с утратой,\r\nотправился в страну мёртвых — Ёми, чтобы вернуть свою жену. Но он нарушил запрет и увидел Идзанами в разложении. В ужасе он бежал, а Идзанами прокляла мир живых. Вернувшись, Идзанаги совершил обряд очищения (мисоги). Из этого ритуала родились: Аматэрасу — из левого глаза, Цукуёми — из правого глаза, Сусаноо — из носа. Так Идзанаги стал отцом главных небесных ками\r\nи установил ритуальную чистоту как основу мира.'),
('kami_S006', 'Izanami-no-Mikoto', 'Идзанами вместе с Идзанаги создала острова и ками,\r\nдавая форму миру и наполняя его жизнью. Она — матерь Японии, из её союза рождается сама структура мира. Рождение бога огня стало роковым. Идзанами умерла от ожогов и покинула мир живых, отправившись в Ёми.Когда Идзанаги увидел её в стране мёртвых, она уже не была прежней. Оскорблённая и разгневанная, Идзанами поклялась ежедневно забирать тысячу жизней. Идзанаги ответил, что каждый день будет рождаться полторы тысячи новых. Так была установлена неизбежность смерти и возрождения.'),
('kami_S007', 'Hachiman', 'Хатиман не участвует в сотворении мира. Он появляется позже, как обожествлённый дух императора Одзина. После смерти Одзин стал почитаться как ками, защищающий страну и воинов. Так возник Хатиман — бог войны не разрушительной, а защитной. С распространением самурайской культуры Хатиман стал покровителем: воинов, кланов, защитников государства. Ему молились не ради хаоса, а ради победы и защиты. Говорят, что во время войны, когда армия была на грани поражения, воинам явился юный лучник. Он не сказал ни слова, но его стрелы указывали путь к победе.'),
('kami_S008', 'Fujin', 'Фудзин считается одним из древнейших ками, возникших ещё в эпоху формирования мира. В ранних текстах он не имеет длинной персональной истории, потому что его роль — стихийная, а не сюжетная. Он воплощает ветер как силу, которая: разгоняет туман, приносит дожди, очищает мир после хаоса. В поздней традиции Фудзин изображается как демоническое существо с мешком ветров за спиной. Считается, что: когда он раскрывает мешок — начинаются ураганы, когда закрывает — наступает покой. Фудзин не злой и не добрый. Он — необходимый хаос, без которого мир застаивается.'),
('kami_S009', 'Raijin', 'Не удалось найти сведения об истории или происхождении'),
('kami_S010', 'Omoikane', 'После того как Аматэрасу скрылась в Небесной Каменной Пещере, мир лишился света, и боги оказались в растерянности. Сила и угрозы не действовали — порядок продолжал рушиться. Тогда ками обратились к Omoikane, божеству размышления и ясного ума. Omoikane не действовал поспешно. Он выслушал богов, обдумал последствия и предложил хитрый, а не силовой план: собрать всех ками у входа в пещеру, приготовить зеркало и священные предметы, устроить шумный праздник, позволить Аме-но-Удзумэ отвлечь Аматэрасу танцем и смехом. Это был план, основанный не на принуждении, а на любопытстве и отражении собственного света.'),
('kami_S011', 'Ebisu', 'Жил однажды бедный рыбак. Каждый день он выходил в море, но улов был скуден. Однажды ночью ему приснился улыбающийся старик и сказал: \"Лови не ради наживы, а ради труда.\", Рыбак продолжил выходить в море, не жалуясь и не обманывая других. Через время его сети стали полными, а лодка — крепкой. Он разбогател, но остался скромным. Говорят, что тем стариком был Ebisu, который приносит удачу тем, кто работает честно и терпеливо.'),
('kami_S012', 'Okuninushi', 'Ōkuninushi известен под множеством имён. Самое раннее и важное из них — Ōnamuchi-no-Kami (大己貴神). Множественность имён подчёркивает его природу: он — ками земли и людей, а не далёкого неба. Ōkuninushi был младшим из многих братьев,\r\nкоторые презирали его и использовали как слугу. Во время странствий братья неоднократно: обманывали его, калечили, убивали. Один из самых известных эпизодов, когда братья заставили его поймать «красного кабана», оказавшегося раскалённым камнем. Ōkuninushi погиб.  Мать Ōkuninushi обратилась к небесным ками, и он был возрождён. Позже, во время новых странствий, его ужалила ядовитая пчела, и он вновь оказался на грани смерти. Именно тогда: мышь, малое существо земли - подсказала ему способ исцеления. Так Ōkuninushi познал лечение через знание природы, а не через божественную силу. И так в кодзиках, свитке I, он впервые становится богом медецины и трав.'),
('kami_S013', 'Kagutsuchi', 'Когда Идзанаги и Идзанами завершали сотворение мира, Идзанами родила последнего из великих ками — Кагуцучи, бога огня. Но это рождение оказалось роковым. Огонь, вышедший из тела богини, сжёг её изнутри, причинив невыносимые муки. Идзанами заболела и вскоре умерла. Так огонь впервые стал: не созиданием, а ценой жизни. Идзанаги, увидев смерть супруги, впервые испытал ярость, не свойственную ками-создателю. Он обнажил меч и разрубил Кагуцучи. Из крови и частей тела огненного бога родились новые ками.'),
('kami_S014', 'Konohanasakuya-hime', 'Небесный внук Аматэрасу — Ninigi-no-Mikoto — спустился на землю, чтобы править миром людей. Ōyamatsumi предложил ему обеих дочерей: Iwanagahime — чтобы жизнь потомков была долгой, Konohanasakuya-hime — чтобы она была прекрасной. Ниниги отверг Iwanagahime, сочтя её некрасивой, и взял в жёны только Konohanasakuya-hime. С этого момента жизнь людей стала короткой, но наполненной красотой. Через короткое время Konohanasakuya-hime забеременела. Ниниги усомнился: \"Ребёнок не может быть моим\". Оскорблённая богиня решила доказать чистоту не словами, а поступком. Она вошла в родильный дом, подожгла его, и родила детей внутри пламени. Если бы дети не были от Ниниги, огонь бы уничтожил их. В огне родились три ками, связанные с огнём и землёй (в разных версиях — с вулканами и огненными горами).'),
('kami_S015', 'Ame-no-Uzume-no-Mikoto', 'Когда Аматэрасу скрылась в Небесной Каменной Пещере, мир лишился света, и порядок начал рушиться. Бедствия и злые духи заполонили землю. Боги собрались, но ни сила, ни уговоры не могли заставить богиню Солнца выйти. Тогда вперёд вышла Аме-но-Удзумэ. Она перевернула бочку, взобралась на неё и начала танцевать — громко, дерзко, нарушая все нормы. Она: обнажила грудь, задрала одежды, смеялась и топала так, что Небеса дрожали. Боги расхохотались. Их смех был настолько громким, что он достиг даже пещеры Аматэрасу. Удивлённая шумом, Аматэрасу приоткрыла вход в пещеру. В этот миг боги показали ей зеркало - и, увидев собственный свет, она вышла наружу. Камень был отодвинут. Солнце вернулось. Мир снова обрёл порядок.'),
('kami_S016', 'Sarutahiko Okami', 'Когда Ninigi-no-Mikoto, внук Аматэрасу, начал своё нисхождение с Неба на Землю, его путь оказался перекрыт. На границе миров стоял странный ками: высокий, с сияющими глазами, с длинным носом, излучающий силу, которую невозможно было игнорировать. Это был Sarutahiko Ōkami. Небесные ками не знали, как пройти мимо Sarutahiko. Тогда вперёд вышла Ame-no-Uzume-no-Mikoto — богиня танца, смеха и жизни. Узуме спросила, почему он стоит на пути.Sarutahiko ответил что он ждёт того, кто сможет назвать его и понять его место. Узуме назвала его имя. Признав её, Sarutahiko отошёл с дороги, указал верный путь, стал проводником нисхождения. Он не просто пропустил Ниниги - он направил движение. Поэтому Sarutahiko почитается как ками дорог, направлений и правильного пути. После исполнения своей роли Sarutahiko отошёл от центра событий. В некоторых традициях он чаще всего уходит к морю, растворяется в мире духов или перестаёт вмешиваться напрямую.'),
('kami_S017', 'Ukemochi no Kami', 'Укэмоти была богиней пищи, которая могла порождать еду из собственного тела. Когда Цукуёми, бог луны, был послан навестить её от имени Аматэрасу, она приготовила угощение. Но способ был странным и земным: рис выходил из её рта, рыба — из тела, мясо — из недр. Для Укэмоти это было естественное порождение жизни. Но Цукуёми, бог чистоты и порядка, воспринял это как осквернение. Не пытаясь понять, он убил Укэмоти. После смерти богини, из её тела появились: рис, пшеница, просо, бобы, домашний скот. Так пища стала доступна людям через жертву.'),
('kami_S018', 'Watatsumi no Kami', 'Не удалось найти сведения об истории или происхождении'),
('kami_S019', 'Oyamatsumi', 'Ōyamatsumi появился в эпоху сотворения мира, когда Идзанаги и Идзанами рождали ками стихий. Он стал воплощением гор — не отдельных вершин, а самой массы земли, её тяжести, устойчивости и древности. Ōyamatsumi — отец Konohanasakuya-hime, богини цветов и весны, и Iwanagahime, богини скал и вечности. Этот союз символичен: цветы — краткая красота, камень — неизменность. Через своих дочерей Ōyamatsumi связывает: \"мимолётность жизни и её фундамент.\"'),
('kami_S020', 'Tenjin', 'Tenjin — это обожествлённый человек: Sugawara no Michizane. Он был учёным, поэтом, государственным деятелем. Но при дворе его оклеветали, лишили титулов и отправили в изгнание, где он умер в бедности и одиночестве. После его смерти в столице начали происходить: пожары, частые молнии, эпидемии, смерти аристократов. Люди решили: \"дух Митидзанэ стал онрё — мстительным духом.\" Чтобы умилостивить его, его возвели в ранг ками — Tenjin, «небесного бога». Со временем образ Tenjin изменился. Он стал защитником учёных, покровителем образования, богом экзаменов и учёбы. Гнев превратился в: ясность ума и силу знания.');
